const state={view:'flow',team:'all',env:'all',service:'order-service',resourceType:'all',mapLayer:'all',codeTab:'runtime',build:'deployed',vpc:'vpc-payments',netMode:'restricted',query:'',agentCase:'payment',agentRan:false,workflow:'proposed',syncRun:false,scaleRun:false,audits:[],securitySeverity:'all'};
/* CORE */
function team(id){return teams.find(t=>t.id===id)}
function svc(id=state.service){return services.find(s=>s.id===id)||services[0]}
function visibleServices(){return services.filter(s=>(state.team==='all'||s.team===state.team)&&(state.env==='all'||s.env===state.env))}
function visibleResources(){const ids=visibleServices().map(s=>s.id);return resources.filter(r=>(state.env==='all'||r.env===state.env)&&(state.team==='all'||r.links.some(id=>ids.includes(id))))}
function visibleEvents(){const ids=visibleServices().map(s=>s.id);return events.filter(e=>ids.includes(e.service))}
function selectedService(){const list=visibleServices();return list.find(s=>s.id===state.service)||list[0]||null}
function statusBadge(status){return ({healthy:'<span class="badge green"><i class="dot"></i>정상</span>',degraded:'<span class="badge amber"><i class="dot"></i>확인 필요</span>',incident:'<span class="badge red"><i class="dot"></i>사건 조사</span>',partial:'<span class="badge blue"><i class="dot"></i>부분 수집</span>'})[status]||badge(status)}
function badge(s,c=''){return `<span class="badge ${c}">${esc(s)}</span>`}
function envLabel(e){return e==='production'?'Production':e==='staging'?'Staging':'On-prem'}
function panel(title,body,action='',sub=''){return `<section class="panel"><div class="panel-head"><h2>${title}${sub?`<small>${sub}</small>`:''}</h2>${action}</div>${body}</section>`}
function goBtn(view,text,cls='btn small'){return `<button class="${cls}" data-go="${view}">${text}</button>`}
function serviceLink(s){return `<button class="link mono" data-service="${s.id}">${esc(s.id)}</button>`}
function stat(label,val,unit,note,color='#adc38b'){return `<article class="stat"><div class="stat-label">${label}<span style="color:#b3becc">↗</span></div><div class="stat-value">${val}<small>${unit}</small></div><div class="stat-note">${note}</div><svg class="spark" viewBox="0 0 70 27" aria-hidden="true"><path d="M0 23L7 20L14 23L21 14L28 17L35 10L42 14L49 6L56 10L63 4L70 6" fill="none" stroke="${color}" stroke-width="1.5"/></svg></article>`}
function table(headers,rows,compact=false){return `<div class="table-wrap${compact?' compact':''}"><table><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${rows.length?rows.join(''):`<tr><td colspan="${headers.length}" class="empty">현재 범위에 표시할 합성 데이터가 없습니다.</td></tr>`}</tbody></table></div>`}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function audit(action,target,result){state.audits.unshift({time:'현재 세션',actor:'전사 운영자 · 합성',action,target,result,mode:'simulated'});state.audits=state.audits.slice(0,12)}
function openDialog(title,subtitle,body,eyebrow='EVIDENCE'){const d=$('#detail-dialog');$('#detail-title').textContent=title;$('#detail-subtitle').textContent=subtitle;$('#detail-eyebrow').textContent=eyebrow;$('#detail-body').innerHTML=body;if(!d.open)d.showModal()}
function ensureSelection(){const list=visibleServices();if(!list.some(s=>s.id===state.service)&&list.length)state.service=list[0].id;const valid=vpcs.filter(v=>(state.env==='all'||v.env===state.env)&&(state.team==='all'||v.teams.includes(state.team)));if(!valid.some(v=>v.id===state.vpc)&&valid.length)state.vpc=valid[0].id}
function navigate(view){if(!pageInfo[view])return;state.view=view;render();$('#content').scrollIntoView({behavior:'instant',block:'nearest'})}
function renderNav(){let html='';navItems.forEach(([id,name,icon,group])=>{if(group)html+=`<div class="nav-group">${group}</div>`;html+=`<div class="nav"><button data-go="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}><span class="nav-icon">${icon}</span>${name}${id==='security'?'<span class="nav-count">'+visibleSecurity().length+'</span>':''}</button></div>`});$('#nav').innerHTML=html;$('#mobile-nav').innerHTML=navItems.map(([id,name])=>`<button data-go="${id}" class="${state.view===id?'active':''}" ${state.view===id?'aria-current="page"':''}>${name}</button>`).join('');$('#scope-team').innerHTML='<option value="all">전사 · 전체 팀</option>'+teams.map(t=>`<option value="${t.id}" ${state.team===t.id?'selected':''}>${t.name} · ${t.owner}</option>`).join('');$('#scope-team').value=state.team;$('#scope-env').value=state.env;$('#crumb-view').textContent=navItems.find(n=>n[0]===state.view)[1];const [eyebrow,title,description]=pageInfo[state.view];$('#eyebrow').textContent=eyebrow;$('#page-title').textContent=title;$('#page-description').textContent=description;$('#scope-meta').textContent=`조회 범위: ${state.team==='all'?'전체 팀':team(state.team).name} · ${state.env==='all'?'모든 환경':envLabel(state.env)} · 서비스 ${visibleServices().length}개 · 기준 14:32 KST`}
function domainCards(){return `<div class="domain-grid">${teams.filter(t=>visibleServices().some(s=>s.team===t.id)).map(t=>{const list=visibleServices().filter(s=>s.team===t.id),bad=list.filter(s=>s.status!=='healthy').length;return `<button class="domain-card" data-domain="${t.id}"><span class="domain-icon">${t.icon}</span><h3>${t.name}</h3><p>${t.summary}</p><div class="domain-meta"><span>${list.length} services</span>${badge(bad?`${bad}개 확인 필요`:'정상',bad?'amber':'green')}</div></button>`}).join('')||'<div class="empty">현재 환경의 서비스가 없습니다.</div>'}</div>`}
function companyMap(){const positions={identity:[8,7],commerce:[39,7],payments:[70,7],community:[8,41],data:[39,41],corporate:[70,41],platform:[23.5,75],security:[54.5,75]};const active=teams.filter(t=>visibleServices().some(s=>s.team===t.id));const pairs=[['platform','commerce','runtime'],['commerce','payments','runtime'],['commerce','identity','runtime'],['community','data','event'],['commerce','data','event'],['payments','data','event'],['corporate','identity','declared'],['security','platform','declared'],['community','identity','declared']];const lines=pairs.filter(([a,b,k])=>active.some(t=>t.id===a)&&active.some(t=>t.id===b)&&(state.mapLayer==='all'||state.mapLayer===k)).map(([a,b,k])=>{const [ax,ay]=positions[a],[bx,by]=positions[b];const x1=(ax+11)*10.6,y1=ay*5.2+54,x2=(bx+11)*10.6,y2=by*5.2+54;const d=Math.abs(y1-y2)<5?(x2>x1?`M${x1+115} ${y1}H${x2-116}`:`M${x1-115} ${y1}H${x2+116}`):`M${x1} ${y1+45}V${(y1+y2)/2}H${x2}V${y2-10}`;return `<path d="${d}" class="map-edge ${k==='declared'?'static':k==='event'?'event':''}"/>`}).join('');return `<div class="map-scroll"><div class="company-map" style="aspect-ratio:1060/520"><svg class="map-svg" viewBox="0 0 1060 520" aria-hidden="true"><defs>${[['arr','#b5c4b5'],['arr-gray','#c1cad7'],['arr-purple','#a49dc1']].map(([id,c])=>`<marker id="${id}" markerWidth="6" markerHeight="6" refX="5" refY="3" orient="auto"><path d="M0 0L6 3L0 6" fill="${c}"/></marker>`).join('')}</defs>${lines}</svg>${active.map(t=>{const list=visibleServices().filter(s=>s.team===t.id);return `<div class="map-domain ${list.some(s=>s.status==='incident')?'hot':''}" style="left:${positions[t.id][0]}%;top:${positions[t.id][1]}%"><div class="map-domain-head"><strong>${t.icon} ${t.name}</strong><span>${list.length} services</span></div>${list.map(s=>`<button class="link mono" data-service="${s.id}">${s.id}<i class="${s.status==='incident'?'error':s.status!=='healthy'?'warn':''}"></i></button>`).join('')}</div>`}).join('')}</div></div><div class="map-foot"><span><i></i>관측된 서비스 관계</span><span><i class="dash"></i>이벤트 연결</span><span><i class="gray"></i>선언된 의존 관계</span><span>여러 실행을 요약한 조직 지도 · 개별 요청의 호출 트리와 구분</span></div>`}
function renderOverview(){const ss=visibleServices(),rr=visibleResources(),ee=visibleEvents(),issues=ss.filter(s=>s.status!=='healthy').length;return `<div class="stats">${stat('등록된 서비스',ss.length,'services',`${new Set(ss.map(s=>s.team)).size}개 팀 · ${new Set(ss.map(s=>s.env)).size}개 환경`)}${stat('연결된 인프라·자산',rr.length,'resources','S3 · VPC · 워크로드 · 데이터베이스','#9cb4ce')}${stat('조사가 필요한 신호',ee.length,'signals',`확인할 서비스 ${issues}개`,'#d2b083')}${stat('관계 갱신 상태',state.syncRun?'재확인':'일부 지연','',state.syncRun?'합성 원본 확인 · 부분 수집 유지':'연결 8개 중 2개 부분 수집','#afa3c5')}</div><div class="grid cols-main"><div class="grid">${panel('회사 전체 시스템',companyMap(),goBtn('map','관계지도 열기 ↗'),'8개 업무·운영 영역')}${panel('업무 시스템과 담당 팀',`<div class="pad">${domainCards()}</div>`,goBtn('catalog','전체 카탈로그 ↗'))}</div><div class="side-panels">${panel('지금 확인할 일',`<div class="pad">${ee.map((e,i)=>`<article class="insight"><span class="insight-icon ${e.kind==='Security'?'red':i>1?'blue':''}">${e.kind==='Security'?'◇':'◷'}</span><div><h3>${e.title}</h3><p>${e.service} · ${e.time} KST</p><button class="link" data-event="${e.id}">근거와 영향 범위 확인 →</button></div></article>`).join('')||'<div class="empty">현재 범위의 조사 신호가 없습니다.</div>'}</div>`,badge('합성 사건','amber'))}${panel('에이전트 조사 시작',`<div class="pad"><p class="subtext">단순 요약 대신, 원본과 버전으로 되돌아갈 수 있는 근거를 조회합니다.</p>${[['payment','결제 오류는 어느 서비스에 영향을 주나요?'],['media','첨부파일 업로드 오류의 관련 근거는?'],['changes','최근 배포와 구성 변경을 함께 볼 수 있나요?']].map(([k,t])=>`<button class="btn" style="width:100%;justify-content:flex-start;margin-bottom:7px;font-size:9px;white-space:normal;text-align:left" data-agent-case="${k}">✧ ${t}</button>`).join('')}</div>`,badge('근거 중심','blue'))}${panel('플랫폼의 상태',`<div class="pad"><div class="metric-line"><span>수집·조회 경로</span>${badge('정상','green')}</div><div class="health-row"><span>분석 큐 · 예산 사용량</span><div class="progress"><i style="width:42%"></i></div><span>42%</span></div><div class="health-row"><span>저장 용량 · 예산 사용량</span><div class="progress"><i style="width:61%"></i></div><span>61%</span></div><div class="metric-line"><span>수집 지연 확인 대상</span><b>2 connectors</b></div>${goBtn('health','수용량·복구 상태 보기 ↗')}</div>`)}</div></div><div class="section-gap">${panel('최근 사건과 변경',table(['참조','대상 서비스','분류','발생 시각','상태'],ee.map(e=>`<tr><td><button class="link" data-event="${e.id}">${e.id}</button><small>${e.title}</small></td><td>${serviceLink(svc(e.service))}</td><td>${e.kind}</td><td>${e.time} KST</td><td>${badge('조사 중',e.severity==='high'?'amber':'blue')}</td></tr>`)),goBtn('sre','사건 목록 ↗'))}</div>`}
/* CORE */
function renderMap(){return `<div class="grid cols-main"><div class="grid">${panel('회사 전체의 관계',companyMap(),`<div class="segmented"><button data-map-layer="all" class="${state.mapLayer==='all'?'active':''}">전체</button><button data-map-layer="runtime" class="${state.mapLayer==='runtime'?'active':''}">관측</button><button data-map-layer="declared" class="${state.mapLayer==='declared'?'active':''}">선언</button><button data-map-layer="event" class="${state.mapLayer==='event'?'active':''}">이벤트</button></div>`,'서비스를 선택해 상세 탐색')}${panel('영역을 넘나드는 탐색',`<div class="pad"><p class="subtext">업무 시스템에서 시작하거나, 자원·네트워크·보안 사건에서 시작해 같은 근거를 따라갑니다.</p><div class="quick-path">${goBtn('catalog','서비스·담당 팀')}${goBtn('code','메서드·실행')}${goBtn('infra','클라우드·저장소')}${goBtn('network','VPC·서브넷')}${goBtn('cmdb','자산·구성 이력')}${goBtn('security','보안 사건')}</div></div>`)}</div><div class="grid">${panel('관계를 읽는 기준',`<div class="pad"><div class="notice green"><strong>하나의 선도 근거를 가집니다.</strong>관계 유형, 출처, 대상 버전, 유효 시간, 수집 시각을 함께 확인합니다.</div><dl class="kv"><dt>관측 관계</dt><dd>실행 기록에서 확인한 호출과 연결</dd><dt>정적 후보</dt><dd>특정 빌드의 코드에서 분석한 호출 가능 관계</dd><dt>선언 관계</dt><dd>서비스·자산 카탈로그에 선언한 의존 관계</dd><dt>구성 관계</dt><dd>배포·VPC·자산의 소속과 설정</dd><dt>미확인</dt><dd>누락·권한·버전 불일치로 결합할 수 없는 관계</dd></dl><p class="subtext section-gap">이 조직 지도는 요약입니다. 개별 요청은 코드·실행 분석에서 해당 빌드와 함께 확인합니다.</p></div>`)}${panel('영향 범위 조사',`<div class="pad"><p class="subtext">서비스 하나의 변경이 어떤 업무 시스템과 공유 자원에 연결되는지 조회합니다. 연결된 관계가 곧 실제 장애 전파를 뜻하지는 않습니다.</p><button class="btn primary" data-agent-case="payment">결제 사건의 근거 조회 ↗</button></div>`)}</div></div>`}
function catalogRows(){const q=(state.catalogQuery||'').toLowerCase();return visibleServices().filter(s=>(s.id+' '+team(s.team).name+' '+s.owner+' '+s.repo).toLowerCase().includes(q)).map(s=>`<tr><td>${serviceLink(s)}<small>${s.path}</small></td><td>${team(s.team).name}<small>${s.owner}</small></td><td>${s.runtime}</td><td>${envLabel(s.env)}</td><td class="mono">build ${s.build}<small>${s.revision}</small></td><td>${statusBadge(s.status)}</td><td><button class="btn small" data-code-service="${s.id}">실행 분석 ↗</button></td></tr>`)}
function renderCatalog(){const list=visibleServices();const rows=catalogRows();return `<div class="stats">${stat('현재 범위의 서비스',list.length,'services','실제 회사 정보가 아닌 합성 카탈로그')}${stat('담당 조직',new Set(list.map(s=>s.team)).size,'teams','명시된 소유권과 운영 책임')}${stat('연결된 자원',visibleResources().length,'resources','공유 자원은 동일한 자산으로 유지')}${stat('상태 확인 대상',list.filter(s=>s.status!=='healthy').length,'services','장애와 수집 누락을 구분','#d1b58b')}</div>${panel('서비스 카탈로그',`<div class="explore-toolbar"><label class="sr-only" for="catalog-filter">서비스·팀·저장소 검색</label><input class="filter-input" id="catalog-filter" value="${esc(state.catalogQuery||'')}" placeholder="서비스 · 팀 · 저장소 검색"><span class="result-count" id="catalog-count">${rows.length}개 표시</span></div>${table(['서비스 / 기능','담당 팀','실행 형태','환경','배포 빌드','상태','탐색'],rows).replace('<tbody>','<tbody id="catalog-rows">')}`,badge('자동 발견 + 선언 출처'))}<div class="section-gap">${panel('업무 시스템',`<div class="pad">${domainCards()}</div>`)}</div>`}
function serviceSelector(){const list=visibleServices();return `<label class="sr-only" for="code-service">분석할 서비스</label><select id="code-service" class="select" style="max-width:260px">${list.map(s=>`<option value="${s.id}" ${s.id===state.service?'selected':''}>${s.id} · ${team(s.team).name}</option>`).join('')}</select>`}
function methodData(s){const main=s.method,base=main.split('.')[0];const entry=s.runtime.includes('consumer')||s.runtime.includes('Streams')?'EventHandler.receive()':s.path.startsWith('RECONCILE')?'ReconcileJob.run()':base.replace(/Service|Handler|Query|Evaluator|Processor|Consumer/,'Controller')+'.handle()';const dependency=s.id==='order-service'?'PaymentClient.authorize()':s.id==='payment-api'?'PaymentRepository.connect()':s.id==='media-service'?'S3Client.putObject()':'DependencyClient.call()';return {entry,main:main+'()',private:'validateInput() · private',dependency,duration:s.p95,depTime:Math.round(s.p95*.86)}}
function renderCode(){const s=selectedService();if(!s)return panel('코드·실행 분석','<div class="empty">현재 범위에 서비스가 없습니다.</div>');const m=methodData(s),old=state.build==='previous',missing=s.id==='notification-worker';const observed=state.codeTab!=='static';return `<div class="panel"><div class="explore-toolbar"><div class="actions">${serviceSelector()}${badge(s.runtime,'blue')}${badge(envLabel(s.env))}</div><div class="actions"><label class="sr-only" for="code-build">코드 분석 빌드</label><select id="code-build" class="select"><option value="deployed" ${!old?'selected':''}>분석 build ${s.build} · 일치</option><option value="previous" ${old?'selected':''}>분석 build ${s.build-1} · 불일치</option></select></div></div><div class="tabline"><button data-code-tab="runtime" class="${state.codeTab==='runtime'?'active':''}">요청 실행</button><button data-code-tab="static" class="${state.codeTab==='static'?'active':''}">정적 호출 후보</button><button data-code-tab="compare" class="${state.codeTab==='compare'?'active':''}">배포·분석 비교</button></div><div class="pad">${old?'<div class="notice"><strong>실행과 분석의 빌드가 달라 코드 연결을 보류했습니다.</strong>런타임이 기록한 이름과 시간은 유지합니다. 이전 빌드의 소스나 정적 관계로 대체하지 않습니다.</div>':missing?'<div class="notice blue"><strong>이 소비자 실행의 원래 요청은 연결 미확인 상태입니다.</strong>추적 문맥이 누락됐습니다. 소비자 실행이 없었다는 뜻은 아닙니다.</div>':`<div class="notice green"><strong>실행 build ${s.build}와 분석 build ${s.build}가 일치합니다.</strong>모듈·산출물·분석기·설정 식별을 함께 확인하는 합성 예시입니다.</div>`}</div></div><div class="grid cols-main section-gap"><div class="grid">${state.codeTab==='compare'?panel('같은 기준으로 비교하기',`<div class="pad"><dl class="kv"><dt>실제 배포</dt><dd>${s.artifact} · build ${s.build}</dd><dt>선택한 분석</dt><dd>build ${old?s.build-1:s.build} · ${old?'결합 보류':'식별 일치'}</dd><dt>이전 빌드 p95</dt><dd>${Math.round(s.p95*.62)} ms · 합성 비교값</dd><dt>현재 빌드 p95</dt><dd>${s.p95} ms · 합성 비교값</dd><dt>비교 조건</dt><dd>같은 업무·환경·부하라는 합성 전제. 실제 동등 조건은 별도 검증해야 합니다.</dd><dt>CPU 시간</dt><dd>미측정 · 0으로 처리하지 않음</dd></dl></div>`):panel(observed?'선택한 요청의 메서드 관계':'해당 빌드의 정적 호출 후보',old&&!observed?'<div class="empty">다른 빌드의 관계를 이 실행에 겹칠 수 없습니다.<br>일치하는 분석 빌드를 선택하세요.</div>':`<div class="method-map"><button class="method-node" data-method="entry"><code>${m.entry}</code><small>${observed?m.duration+' ms · 관측':'해당 빌드의 호출 후보'}</small></button><span class="method-arrow">↓</span><button class="method-node" data-method="main"><code>${m.main}</code><small>${observed?Math.max(1,m.duration-8)+' ms · 관측':'동일 모듈의 호출 후보'}</small></button><span class="method-arrow">↙　↘</span><div class="method-branches"><button class="method-node" data-method="private"><code>${m.private}</code><small>${observed?'3 ms · 자체 호출 관측':'private / self-call 후보'}</small></button><button class="method-node hot" data-method="dependency"><code>${m.dependency}</code><small>${observed?m.depTime+' ms · 경과 시간':'외부 연동 경계의 후보'}</small></button></div>${!observed?'<span class="method-arrow">⋮</span><div class="method-node candidate"><code>DynamicPlugin.invoke()</code><small>미해결 · 실행 대상을 확정할 근거 부족</small></div>':''}</div>`,badge(observed?'합성 실행':'정적 분석 예시',observed?'green':'blue'))}${panel('요청과 비동기 실행',`<div class="pad"><div class="actions" style="justify-content:space-between;margin-bottom:10px"><span class="mono small">${esc(s.path)}</span>${badge(s.status==='incident'?'timeout 예시':'업무 결과 예시',s.status==='incident'?'amber':'green')}</div>${[[m.entry,0,100,m.duration],[m.main,1,97,Math.max(1,m.duration-8)],[m.private,3,2,3],[m.dependency,8,86,m.depTime]].map(([name,x,w,time],i)=>`<div class="waterfall-row"><span class="mono">${name}</span><div class="waterfall-track"><i class="${i===3?'hot':''}" style="--x:${x}%;--w:${w}%"></i></div><span>${time} ms</span></div>`).join('')}<p class="subtext" style="font-size:8px;margin:12px 0 0">중첩 구간을 단순 합산하지 않습니다. 앱 패키지와 일부 요청만 수집한 예시입니다. 비동기 실행은 parent/link 근거가 있을 때만 연결합니다.</p></div>`,badge('부분 수집','blue'))}</div><div class="grid">${panel('실행·분석의 식별',`<div class="pad"><dl class="kv"><dt>Repository</dt><dd class="mono">${s.repo}</dd><dt>Revision</dt><dd class="mono">${s.revision}</dd><dt>Build</dt><dd class="mono">${s.build}</dd><dt>Artifact</dt><dd class="mono">${s.artifact}</dd><dt>Module</dt><dd class="mono">${s.module}</dd><dt>Analyzer</dt><dd>fixture-analyzer 0.3</dd><dt>Schema / config</dt><dd>v1 / app-only-r7</dd><dt>관측 구간</dt><dd>14:20–14:32 KST · 10% 표본 예시</dd><dt>출처</dt><dd>합성 코드 분석 + 실행 fixture</dd></dl><button class="btn section-gap" data-evidence-json>구조화된 근거 보기 ↗</button></div>`)}${panel('다른 영역으로 이어서 조사',`<div class="pad"><div class="flow-strip"><span>${s.id}</span><i>→</i><span>당시 배포·자산</span></div><div class="actions">${goBtn('infra','인프라')}${goBtn('network','네트워크')}${goBtn('cmdb','변경 이력')}${goBtn('security','보안 사건')}</div></div>`)}</div></div>`}
function resourceRows(){return visibleResources().filter(r=>state.resourceType==='all'||r.category===state.resourceType).map(r=>`<tr><td><button class="link mono" data-resource="${r.id}">${r.id}</button><small>${r.name}</small></td><td>${badge(r.type)}</td><td>${envLabel(r.env)}</td><td>${team(r.team).name}</td><td>${r.links.filter(id=>visibleServices().some(s=>s.id===id)).length}개 서비스</td><td>${statusBadge(r.status)}</td><td><button class="btn small" data-resource="${r.id}">상세 ↗</button></td></tr>`)}
function renderInfra(){const rr=visibleResources(),types=[['all','전체'],['Compute','실행'],['Storage','저장소'],['Data','데이터'],['Messaging','메시징'],['Network','네트워크'],['Security','권한·보안']];return `<div class="stats">${stat('현재 범위의 자원',rr.length,'resources','AWS · Kubernetes · 온프레미스')}${stat('실행·저장·데이터',rr.filter(r=>['Compute','Storage','Data'].includes(r.category)).length,'resources','EKS · ECS · S3 · RDS · VM')}${stat('네트워크·보안',rr.filter(r=>['Network','Security'].includes(r.category)).length,'resources','VPC · Subnet · IAM · KMS')}${stat('확인할 구성 자산',rr.filter(r=>r.status!=='healthy').length,'resources','변경·오류·수집 범위 대조','#d3b58b')}</div>${panel('인프라 자원 목록',`<div class="explore-toolbar"><div class="resource-filter">${types.map(([id,name])=>`<button data-resource-type="${id}" class="${state.resourceType===id?'active':''}">${name}</button>`).join('')}</div><span class="result-count">${resourceRows().length}개 표시</span></div>${table(['자원 / 역할','유형','환경','자산 담당 팀','서비스 연결','상태','탐색'],resourceRows())}`,badge('공급원별 자원 식별'))}<div class="grid cols-3 section-gap">${[['S3·객체 저장소','버킷과 실행 역할, 암호화 키, 접근 경로, 관련 이벤트를 연결합니다. 버킷을 서브넷 내부의 서버로 표현하지 않습니다.','s3-community-media'],['워크로드·배포','서비스의 논리 식별과 실제 Pod·task·VM의 수명을 구분합니다. 재배포·확장 전후의 연결을 보존합니다.','eks-commerce'],['공유 자원','여러 서비스가 쓰는 데이터베이스·이벤트 스트림·네트워크를 같은 자원으로 유지합니다.','kafka-business']].map(([t,d,id])=>panel(t,`<div class="pad"><p class="subtext">${d}</p>${visibleResources().some(r=>r.id===id)?`<button class="btn small" data-resource="${id}">예시 자원 확인 ↗</button>`:badge('현재 조회 범위 밖')}</div>`)).join('')}</div>`}
function renderNetwork(){const valid=vpcs.filter(v=>(state.env==='all'||v.env===state.env)&&(state.team==='all'||v.teams.includes(state.team)));if(!valid.length)return panel('네트워크','<div class="empty">현재 범위의 네트워크가 없습니다.</div>');const v=valid.find(v=>v.id===state.vpc)||valid[0],ns=subnetRows.filter(n=>n.vpc===v.id),base=ns[1].cidr.split('.').slice(0,2).join('.'),isAws=v.env!=='onprem',restricted=state.netMode==='restricted';const netService=visibleServices().find(s=>s.env===v.env&&v.teams.includes(s.team));return `${panel('네트워크 영역',`<div class="explore-toolbar"><label class="sr-only" for="network-vpc">네트워크 선택</label><select id="network-vpc" class="select" style="max-width:260px">${valid.map(x=>`<option value="${x.id}" ${x.id===v.id?'selected':''}>${x.id} · ${x.cidr}</option>`).join('')}</select><div class="segmented"><button data-net-mode="restricted" class="${restricted?'active':''}">차단 상황</button><button data-net-mode="normal" class="${!restricted?'active':''}">허용 상황</button></div></div><div class="pad"><div class="network-container"><div class="network-title"><strong>${isAws?'VPC':'사이트 네트워크'} ${v.id} · <code>${v.cidr}</code></strong><span>${v.account} · ${v.region}</span></div><div class="subnets">${ns.map((n,i)=>`<section class="subnet"><h3>${n.name}</h3><p class="mono">${n.cidr} · ${n.id}</p><div class="network-node">${i===0?'Load balancer / ingress':i===1?(netService?netService.id:'Application workload'):'Database endpoint'}<small>${base}.${[1,10,20][i]}.${[12,24,8][i]} · ${isAws?'ENI fixture-'+i:'NIC fixture-'+i}</small></div><div class="network-node">${i===0?'진입 규칙':i===1?'앱 송신 규칙':'데이터 접근 규칙'}<small>${isAws?'Security Group + NACL':'Firewall policy'} · config-r${i+7}</small></div></section>`).join('')}</div></div><div class="quick-path"><span>소속 관계</span><span>워크로드 → ENI / NIC → 서브넷 → VPC / 사이트</span><span>· 실제 통신 경로와 구분</span></div></div>`,badge('구성 관계','green'))}<div class="grid cols-2 section-gap">${panel('설정상 통신 경로',`<div class="pad"><div class="flow-strip"><span>App ${base}.10.24</span><i>→</i><span>Route · 경계 규칙</span><i>→</i><span>DB ${base}.20.8:5432</span></div><div class="notice ${restricted?'':'green'}"><strong>${restricted?'현재 합성 설정에서 해당 경로의 접근이 제한됩니다.':'현재 합성 설정에서 해당 경로의 접근이 허용됩니다.'}</strong>네트워크 구성에 대한 판정 예시입니다. 실제 패킷 시험이나 전체 구간의 정상 동작을 입증하지 않습니다.</div><div class="rule-diff"><span class="mono">${isAws?'SG':'Firewall'} rule · fixture-rule-17</span><span class="removed">이전: source ${ns[1].cidr} → TCP 5432 allow</span><span class="${restricted?'removed':'added'}">현재: source ${restricted?base+'.99.0/24':ns[1].cidr} → TCP 5432 allow</span></div><p class="subtext section-gap" style="font-size:9px;margin-bottom:0">사건 당시의 구성 snapshot과 유효 시간을 대조합니다. 설정과 관측 기록의 원본은 각각 보존합니다.</p></div>`,badge('구성 분석 예시',restricted?'amber':'green'))}${panel('관측된 통신 기록',table(['관측 구간','출발지 → 목적지','포트·프로토콜','동작'],[`<tr><td>14:28–14:29</td><td class="mono">${base}.10.24 → ${base}.20.8<small>인터페이스별 집계 · flow-fixture-17</small></td><td>5432 / TCP</td><td>${badge(restricted?'REJECT':'ACCEPT',restricted?'red':'green')}</td></tr>`,`<tr><td>14:29–14:30</td><td class="mono">${base}.1.12 → ${base}.10.24<small>별도 통신 관측 · flow-fixture-18</small></td><td>443 / TCP</td><td>${badge('ACCEPT','green')}</td></tr>`],true)+`<div class="pad"><p class="subtext" style="margin:0">통신 기록만으로 특정 메서드나 Trace ID를 확정하지 않습니다. 시각·포트·실행 자원과 NAT·IP 재사용을 고려한 추가 연결 근거가 필요합니다.</p></div>`,badge('합성 Flow Logs','blue'))}</div>`}
function renderCmdb(){const rr=visibleResources();return `<div class="stats">${stat('관리 자산',rr.length,'assets','논리 서비스와 실제 자산 식별 분리')}${stat('소유 조직',new Set(rr.map(r=>r.team)).size,'teams','현재 소유권과 당시 책임을 구분')}${stat('확인할 구성 변경',Math.min(3,rr.filter(r=>r.status!=='healthy').length),'changes','공급원·유효 시간·설정 revision')}${stat('관계 이력','보존','','최신 상태로 과거 관계를 덮어쓰지 않음','#9db7cb')}</div><div class="grid cols-main"><div>${panel('자산과 구성',table(['자산 식별','유형','담당 팀','현재 설정','원본'],rr.map(r=>`<tr><td><button class="link mono" data-resource="${r.id}">${r.id}</button><small>${r.name}</small></td><td>${r.type}</td><td>${team(r.team).name}</td><td class="mono">${r.revision}</td><td>${r.source}<small>14:32:08 KST</small></td></tr>`)))}</div><div class="grid">${panel('최근 구성·관계 이력',`<div class="pad"><div class="mini-timeline">${visibleEvents().map(e=>`<div class="timeline-item amber"><strong>${e.time} · ${e.title}</strong><small>${e.service} · 원본·변경 revision 확인</small><div style="margin-top:6px"><button class="link" data-event="${e.id}">관련 근거 확인 →</button></div></div>`).join('')||'<div class="timeline-item"><strong>현재 범위의 변경 사건이 없습니다.</strong><small>합성 예시의 현재 조회 범위</small></div>'}</div></div>`)}${panel('관계와 책임의 시간',`<div class="pad"><dl class="kv"><dt>논리 서비스</dt><dd>담당 팀·저장소·업무 시스템</dd><dt>배포 자원</dt><dd>환경·빌드·Pod/task·생존 구간</dd><dt>공유 자산</dt><dd>자산 소유자와 사용 서비스</dd><dt>유효 시간</dt><dd>언제부터 언제까지 유효했는지</dd><dt>수집 시간</dt><dd>플랫폼이 언제 원본을 확인했는지</dd><dt>연결 실패</dt><dd>삭제로 간주하지 않고 미확인 유지</dd></dl></div>`)}</div></div>`}
const securitySignals=[{id:'SEC-208',service:'media-service',title:'미디어 저장소 정책 변경과 접근 오류',severity:'high',source:'IAM change + storage access metadata',state:'조사 중',time:'14:24',detail:'실행 역할 정책에서 객체 쓰기 권한 범위가 바뀐 예시입니다. 같은 시간대 오류와 원인 관계를 추가 확인합니다.'},{id:'SEC-209',service:'api-gateway',title:'공용 API 정책의 거절 증가',severity:'medium',source:'WAF event summary',state:'관측 사실',time:'14:26',detail:'정책 거절 집계가 증가했습니다. 공격 성공이나 서비스 침해를 판정한 결과가 아닙니다.'},{id:'SEC-210',service:'payment-api',title:'DB 경계의 통신 거절 기록',severity:'medium',source:'Flow metadata + configuration',state:'구성 대조',time:'14:28',detail:'합성 통신 기록의 거절과 당시 접근 규칙을 대조합니다. 거절 로그 하나로 특정 규칙이나 요청을 확정하지 않습니다.'},{id:'SEC-211',service:'audit-worker',title:'감사 저장소의 수집 범위 공백',severity:'low',source:'Collector coverage state',state:'수집 확인',time:'14:20',detail:'객체 데이터 이벤트의 일부 범위가 비활성인 상황입니다. 로그가 없다는 이유로 접근이 없었다고 판단하지 않습니다.'},{id:'SEC-212',service:'member-service',title:'서비스 역할 변경의 영향 검토',severity:'low',source:'Role change metadata',state:'검토 대기',time:'14:18',detail:'서비스 계정의 역할 변경을 자산 소유권·현재 정책과 함께 검토하는 예시입니다.'}];
function visibleSecurity(){const ids=visibleServices().map(s=>s.id);return securitySignals.filter(e=>ids.includes(e.service))}
function renderSre(){const ss=visibleServices(),incidents=visibleEvents().filter(e=>e.kind==='SRE'),rps=ss.reduce((n,s)=>n+s.rps,0);return `<div class="stats">${stat('서비스 목표 이탈',ss.filter(s=>s.slo<99.9).length,'services','예시 가용성 목표 99.9% · 합성 창')}${stat('조사 중인 운영 사건',incidents.length,'incidents','신호와 확정 원인을 구분','#d5b18a')}${stat('현재 처리량 예시',rps.toLocaleString(),'req/s','서비스별 합성 부하의 합계','#a4b7ce')}${stat('확장·복구 상태',state.scaleRun?'확장 재현':'관찰 중','',state.scaleRun?'플랫폼 worker 3 → 5 · 로컬 표시':'업무 부하와 수집 부하를 따로 확인')}</div><div class="grid cols-main"><div class="grid">${panel('서비스별 신뢰성 목표',table(['서비스','가용성 예시','예산 잔여','응답 p95','오류율','조사'],ss.map(s=>{const budget=Math.max(0,Math.min(100,Math.round((s.slo-99.9)/.1*100)));return `<tr><td>${serviceLink(s)}<small>${team(s.team).name}</small></td><td>${s.slo.toFixed(2)}%<small>목표 99.90%</small></td><td><div class="progress ${budget<20?'amber':''}"><i style="width:${budget}%"></i></div><small>${budget}% · 합성 창</small></td><td>${s.p95} ms</td><td>${s.error}%</td><td><button class="btn small" data-code-service="${s.id}">실행 ↗</button></td></tr>`})))}${panel('운영 사건',table(['사건','대상 서비스','발생 시각','근거'],incidents.map(e=>`<tr><td><button class="link" data-event="${e.id}">${e.id} · ${e.title}</button></td><td>${serviceLink(svc(e.service))}</td><td>${e.time}</td><td>${goBtn('network','구성·통신 대조 ↗')}</td></tr>`)))}</div><div class="grid">${panel('관측 신호를 함께 보기',`<div class="pad"><p class="subtext">메트릭·로그·트레이스·프로파일을 같은 대상·빌드·시간 범위에서 탐색합니다.</p><div class="metric-line"><span>메트릭</span><b>요청률·오류율·경과 시간</b></div><div class="metric-line"><span>로그</span><b>허용된 오류 메타데이터</b></div><div class="metric-line"><span>트레이스</span><b>실행 부모·비동기 링크</b></div><div class="metric-line"><span>프로파일</span><b>빌드·프로세스별 샘플</b></div><button class="btn section-gap" data-signals>로그·프로파일 예시 ↗</button></div>`)}${panel('자동 확장과 수용량',`<div class="pad"><p class="subtext">대상 서비스의 확장을 관측하는 일과 플랫폼 자신의 용량을 조절하는 일을 구분합니다.</p><div class="metric-line"><span>플랫폼 처리 worker</span><b>${state.scaleRun?'5':'3'} replicas</b></div><div class="metric-line"><span>소비 큐 예산 사용량</span><b>${state.scaleRun?'31':'67'}%</b></div><button class="btn" data-scale>확장 결과 시뮬레이션</button><p class="subtext" style="font-size:8px;margin:11px 0 0">실제 확장이나 성능 검증을 수행하지 않습니다. 고정 자원·장애·복구 중 수용량도 별도로 검증해야 합니다.</p></div>`)}${panel('계측 비용 비교',`<div class="pad"><div class="metric-line"><span>계측 OFF 처리량 예시</span><b>2,370 req/s</b></div><div class="metric-line"><span>계측 ON 처리량 예시</span><b>2,290 req/s</b></div><p class="subtext" style="margin:10px 0 0">화면 검토용 합성 비교값입니다. 지원 성능이나 실제 측정 결과로 해석하지 않습니다.</p></div>`,badge('합성 비교','blue'))}</div></div>`}
function renderSecurity(){const all=visibleSecurity(),list=all.filter(e=>state.securitySeverity==='all'||e.severity===state.securitySeverity);return `<div class="stats">${stat('검토할 보안 신호',all.length,'signals','허용된 이벤트 메타데이터만 표시','#cba195')}${stat('높은 우선순위',all.filter(e=>e.severity==='high').length,'signals','관련 근거와 구성 이력 대조','#d2ad83')}${stat('연관된 서비스',new Set(all.map(e=>e.service)).size,'services','자산 식별과 유효 시점 기준')}${stat('사건의 원인 판정','검토 중','','시간적 연관성을 확정 원인으로 처리하지 않음','#b4a7cb')}</div>${panel('보안 이벤트와 조사',`<div class="explore-toolbar"><div class="resource-filter">${[['all','전체'],['high','높음'],['medium','중간'],['low','낮음']].map(([k,n])=>`<button data-severity="${k}" class="${state.securitySeverity===k?'active':''}">${n}</button>`).join('')}</div><span class="result-count">${list.length}개 표시</span></div>${table(['이벤트','서비스·자산 연결','우선순위','원본 유형','조사 상태'],list.map(e=>`<tr><td><button class="link" data-security="${e.id}">${e.id} · ${e.title}</button><small>${e.time} KST · 합성 이벤트</small></td><td>${serviceLink(svc(e.service))}</td><td>${badge(e.severity,e.severity==='high'?'red':e.severity==='medium'?'amber':'blue')}</td><td>${e.source}</td><td>${badge(e.state)}</td></tr>`))}`,badge('SIEM · 보안 사건'))}<div class="grid cols-3 section-gap">${panel('자산에서 시작하는 조사',`<div class="pad"><p class="subtext">저장소·네트워크·워크로드·계정의 안정적인 식별자를 기준으로 관련 신호를 모읍니다.</p>${goBtn('cmdb','자산과 변경 이력 ↗')}</div>`)}${panel('운영 대응의 경계',`<div class="pad"><p class="subtext">이벤트 조회 권한이 변경 실행 권한을 의미하지는 않습니다. 조치 제안·승인·실행·결과를 따로 남깁니다.</p>${goBtn('automation','승인·실행 흐름 ↗')}</div>`)}${panel('원본과 수집 범위',`<div class="pad"><p class="subtext">본문·토큰·회원 정보는 표시하지 않습니다. 일부 수집 누락과 현재 접근 권한을 근거 응답에 포함합니다.</p>${goBtn('connectors','수집 상태 확인 ↗')}</div>`)}</div>`}
const agentCases={payment:{question:'결제 오류와 연결된 서비스·네트워크·변경 근거를 보여줘.',service:'payment-api',facts:[['실행 근거','결제 API의 DB 연결 시간 초과가 관측된 합성 요청입니다.','code'],['네트워크 근거','같은 구간의 통신 거절 기록과 접근 규칙 변경을 별도로 확인합니다.','network'],['영향 관계','주문 서비스의 결제 호출과 정산의 이벤트 관계를 조회합니다. 연결 자체가 장애 전파의 확정 증거는 아닙니다.','map']],limits:['통신 집계와 특정 요청의 일대일 대응은 추가 확인 필요','시간상 가까운 변경을 확정 원인으로 판단하지 않음']},media:{question:'첨부파일 업로드 오류와 S3·IAM·KMS 관련 근거를 보여줘.',service:'media-service',facts:[['실행 근거','미디어 서비스의 객체 업로드 호출에서 접근 오류가 발생한 합성 예시입니다.','code'],['자원·권한','S3 버킷, 실행 역할, 암호화 키와 endpoint 경로를 연결합니다.','infra'],['변경·보안','역할 정책 변경과 오류 발생을 해당 시점의 근거로 대조합니다.','security']],limits:['S3 객체 데이터 이벤트 일부 범위 미수집','정책 변경과 오류의 인과관계는 미확정']},changes:{question:'최근 코드 배포와 인프라·보안 구성 변경을 함께 보여줘.',service:'order-service',facts:[['코드·빌드','분석 revision과 실제 배포 artifact를 구분하고 각 빌드의 근거를 보존합니다.','code'],['구성·자산','자원의 설정 revision과 소유권 변경을 유효 시간에 맞춰 조회합니다.','cmdb'],['수집·갱신','알림 수신과 원본 재확인, 마지막 성공 반영을 분리해서 확인합니다.','connectors']],limits:['원본을 확인하지 못한 과거 구간은 복원 완료로 표시하지 않음','다른 빌드의 메서드를 묵시적으로 결합하지 않음']}};
function evidenceBundle(){const c=agentCases[state.agentCase],s=svc(c.service);return {synthetic:true,organization:'tong-works-fixture',scope:{team:state.team,environment:state.env},query:c.question,subject:{service:s.id,repository:s.repo,revision:s.revision,build:s.build,artifact:s.artifact,module:s.module},analysis:{analyzer:'fixture-0.3',schema:'v1',config:'app-only-r7'},time:{observed_window:'2026-11-12T14:20:00+09:00/2026-11-12T14:32:00+09:00',retrieved_at:'2026-11-12T14:32:08+09:00'},evidence:c.facts.map(([type,summary,view],i)=>({id:'fixture-evidence-'+i,type,summary,source:'inline synthetic fixture',relationship:view,certainty:'fixture_fact'})),limitations:c.limits,causality:'not_established',external_actions:[],agent_execution:'not_executed'}}
function renderAgent(){const c=agentCases[state.agentCase],allowed=visibleServices().some(s=>s.id===c.service),s=svc(c.service);return `${panel('분석 질문',`<div class="pad"><div class="pill-list">${[['payment','결제·네트워크'],['media','S3·권한'],['changes','배포·구성 변경']].map(([k,n])=>`<button data-agent-case="${k}" class="${state.agentCase===k?'active':''}">${n}</button>`).join('')}</div><form class="agent-input" id="agent-form"><label class="sr-only" for="agent-query">조회할 분석 질문</label><input id="agent-query" maxlength="150" value="${esc(state.agentInput||c.question)}"><button class="btn primary" type="submit">근거 조회 재현 →</button></form><p class="subtext" style="font-size:9px;margin:0">등록된 질문의 합성 근거를 반환하는 체험입니다. 실제 AI 호출이나 자유 질의 분석은 수행하지 않습니다.</p></div>`,badge(state.agentRan?'조회 예시 갱신':'읽기 전용 예시','blue'))}${state.agentUnsupported?'<div class="notice section-gap">이 질문에 대한 합성 응답은 준비되어 있지 않습니다. 위의 결제·S3·변경 예시 중 하나를 선택해 조회 흐름을 확인하세요.</div>':!allowed?'<div class="notice section-gap">현재 팀·환경 필터에 질문의 대상 서비스가 없습니다. 조회 범위를 바꾸거나 범위에 맞는 질문을 선택하세요.</div>':`<div class="grid cols-main section-gap"><div>${panel('사실·관계·한계를 구분한 응답',`<div class="pad"><div class="agent-question">✧ ${c.question}</div>${c.facts.map(([t,d,v],i)=>`<article class="finding"><div class="actions" style="justify-content:space-between;margin-bottom:7px"><strong>${i+1}. ${t}</strong>${badge('합성 근거','green')}</div><p>${d}</p><button class="link" data-agent-evidence="${v}">원본 영역에서 확인 →</button></article>`).join('')}<div class="notice" style="margin-top:13px;margin-bottom:0"><strong>함께 전달하는 한계</strong>${c.limits.map(l=>'• '+l).join('<br>')}</div></div>`,badge('원인 확정 없음','amber'))}</div><div class="grid">${panel('조회에 포함한 식별',`<div class="pad"><dl class="kv"><dt>대상</dt><dd>${s.id}</dd><dt>저장소</dt><dd class="mono">${s.repo}</dd><dt>Revision</dt><dd class="mono">${s.revision}</dd><dt>Build</dt><dd>${s.build}</dd><dt>Artifact</dt><dd class="mono">${s.artifact}</dd><dt>분석 범위</dt><dd>app-only-r7 · schema v1</dd><dt>발생 구간</dt><dd>14:20–14:32 KST</dd><dt>출처</dt><dd>합성 실행·분석·구성 fixture</dd></dl><button class="btn section-gap" data-agent-json>에이전트 응답 JSON ↗</button></div>`)}${panel('같은 근거를 함께 사용',`<div class="pad"><p class="subtext" style="margin:0">화면과 API가 서로 다른 최신 결과를 해석하지 않도록, 동일한 식별·시점·권한 범위의 근거를 조회하는 제품 방향입니다.</p></div>`)}</div></div>`}`}
function renderAutomation(){const phase={proposed:0,approved:1,completed:3}[state.workflow];return `<div class="stats">${stat('자동화 경로','4','workflows','발견 · 분석 · 갱신 · 운영 실행')}${stat('원본 재확인',state.syncRun?'완료':'대기','',state.syncRun?'현재 세션에서 합성 결과 반영':'변경 알림과 주기 확인의 조합')}${stat('운영 변경 요청',state.workflow==='completed'?'재현 완료':state.workflow==='approved'?'승인됨':'검토 대기','','실제 외부 변경 없음','#c7b18d')}${stat('세션 감사 기록',state.audits.length,'events','요청·승인·실행 결과의 분리')}</div><div class="grid cols-2">${panel('발견·분석·관계 갱신',`<div class="pad"><p class="subtext">GitHub 변경 알림을 받은 뒤 실제 원본을 확인하고 해당 빌드의 분석 결과를 게시하는 흐름입니다.</p><div class="action-steps">${['변경 감지','원본 확인','분석·검증','관계 반영'].map((n,i)=>`<div class="action-step ${state.syncRun?'done':i===0?'active':''}">${i+1}. ${n}</div>`).join('')}</div><dl class="kv"><dt>처리 기준</dt><dd>원본 revision + 분석 범위 + 설정 버전</dd><dt>실패 시</dt><dd>마지막 성공 결과 유지 · 갱신 지연 표시</dd><dt>누락 복구</dt><dd>주기적인 원본 재확인 · 과거 공백은 구분</dd><dt>실행 결과</dt><dd>${state.syncRun?'현재 세션의 합성 결과 반영 완료':'원본 재확인 대기 예시'}</dd></dl><button class="btn primary section-gap" data-sync>재확인·반영 시뮬레이션</button></div>`,badge('수집·갱신'))}${panel('운영 조치 제안과 실행',`<div class="pad"><p class="subtext">관측 플랫폼의 worker 확장 제안을 예로, 조회 권한과 실행 권한을 구분합니다.</p><div class="action-steps">${['조치 제안','승인 확인','실행 요청','결과·감사'].map((n,i)=>`<div class="action-step ${i<phase||state.workflow==='completed'?'done':i===phase?'active':''}">${i+1}. ${n}</div>`).join('')}</div><dl class="kv"><dt>대상</dt><dd>플랫폼 connector worker · 합성 환경</dd><dt>변경</dt><dd>replicas 3 → 5 · 예산 범위 내</dd><dt>승인 정책</dt><dd>변경 실행 전 승인·범위·현재 정책 확인</dd><dt>되돌리기</dt><dd>replicas 5 → 3 · 예산·업무 영향 재검토</dd><dt>현재 상태</dt><dd>${state.workflow==='completed'?'실행·감사 완료를 재현함':state.workflow==='approved'?'승인 절차 재현 완료 · 실행 가능':'조치 제안 · 승인 전'}</dd></dl><div class="actions section-gap"><button class="btn" data-review-action>제안 검토</button><button class="btn primary" data-run-action ${state.workflow!=='approved'?'disabled':''}>실행 재현</button></div><p class="subtext" style="font-size:8px;margin:12px 0 0">승인과 실행은 모두 목업 안의 상태 전환입니다. 클라우드나 클러스터에 명령을 보내지 않습니다.</p></div>`,badge('정책 기반 실행','amber'))}</div><div class="section-gap">${panel('이번 세션의 감사 기록',auditTable(),goBtn('governance','권한·감사 정책 ↗'))}</div>`}
function auditTable(){return table(['시각','행위자','동작','대상','결과'],state.audits.map(a=>`<tr><td>${a.time}</td><td>${a.actor}</td><td>${a.action}</td><td>${a.target}</td><td>${badge(a.result,'blue')}<small>simulated</small></td></tr>`))}
function renderConnectors(){return `<div class="notice blue"><strong>공급원 연결과 영역별 준비 상태를 구분합니다.</strong>서비스 등록 성공이 코드 분석·실행 계측·클라우드·보안 수집 완료를 의미하지는 않습니다. 아래는 전사 연결 상태의 합성 예시입니다.</div><div class="grid cols-3">${connectors.map(c=>`<section class="connector-card"><div class="connector-top"><h3>${c.name}</h3>${statusBadge(state.syncRun&&c.id==='github'?'healthy':c.state)}</div><p>${c.scope}</p><dl class="kv"><dt>마지막 확인</dt><dd>${state.syncRun&&c.id==='github'?'현재 세션 · 합성 반영':c.last+' KST'}</dd><dt>수집·권한</dt><dd>${c.detail}</dd></dl><button class="btn small section-gap" data-connector="${c.id}">연결 범위와 근거 ↗</button></section>`).join('')}</div><div class="grid cols-2 section-gap">${panel('자동 등록의 출처',`<div class="pad"><div class="flow-strip"><span>허용한 저장소</span><i>→</i><span>서비스 선언·후보</span><i>→</i><span>정책·충돌 확인</span><i>→</i><span>카탈로그 반영</span></div><p class="subtext">선언으로 확인한 서비스와 분석으로 추정한 후보를 구분합니다. 커미터를 담당자로 자동 확정하지 않습니다.</p>${goBtn('catalog','발견된 서비스 보기 ↗')}</div>`)}${panel('원본 재확인과 누락 복구',`<div class="pad"><p class="subtext">변경 알림은 빠른 갱신을 돕고, 주기적인 원본 확인은 놓친 변경과 오래된 관계를 점검합니다.</p><div class="metric-line"><span>최근 반영 상태</span>${badge(state.syncRun?'재확인 완료':'지연된 원본 1개',state.syncRun?'green':'amber')}</div><button class="btn primary section-gap" data-sync>원본 재확인 시뮬레이션</button></div>`)}</div>`}
function renderGovernance(){return `<div class="notice blue"><strong>조직·권한·감사는 전사 관리 영역입니다.</strong>상단 팀·환경 선택은 탐색 필터입니다. 실제 인증·조직 격리·인가를 구현하거나 검증한 목업은 아닙니다.</div><div class="grid cols-3">${[['사람과 팀','전사 운영자 · 개발 팀 · SRE · 보안 담당자','조직·팀·역할·자원·환경에 따른 접근 범위를 관리합니다.'],['서비스 계정','수집기 · CI 분석 작업 · 자동화 실행기','공급원 연결 권한과 사용자 조회 권한, 변경 실행 권한을 구분합니다.'],['분석 에이전트','사용자를 대신하는 읽기 조회','누구의 권한으로 어떤 범위·시점의 근거를 조회했는지 기록합니다.']].map(([t,s,d])=>panel(t,`<div class="pad"><strong class="small">${s}</strong><p class="subtext section-gap" style="margin-bottom:0">${d}</p></div>`)).join('')}</div><div class="grid cols-2 section-gap">${panel('역할과 정책 예시',`<div class="pad"><div class="role-card"><strong>팀 개발자</strong><p>자기 팀의 서비스·실행·연결된 허용 자원을 조회합니다. 운영 변경은 별도 정책을 따릅니다.</p></div><div class="role-card section-gap"><strong>보안 분석 담당자</strong><p>허용된 보안 이벤트 요약과 관련 자산을 조사합니다. 민감 원본과 조치 권한은 별도입니다.</p></div><div class="role-card section-gap"><strong>운영 변경 승인자·실행기</strong><p>제안·승인·실행·결과를 분리하고 위임 범위와 현재 권한을 재확인합니다.</p></div></div>`)}${panel('데이터 수명주기 예시',`<div class="pad"><dl class="kv"><dt>근거 보존</dt><dd>데이터 유형과 조직 정책별 보존 기간</dd><dt>권한 회수</dt><dd>새 수집·캐시·검색·과거 결과의 접근 재평가</dd><dt>삭제</dt><dd>색인·복제본·백업·복원 후 처리까지 추적</dd><dt>민감 정보</dt><dd>인수·반환 본문·토큰의 기본 수집 제외</dd><dt>감사</dt><dd>행위자·대리 신원·대상·정책·실제 결과</dd></dl><div class="notice section-gap" style="margin-bottom:0">설정과 정책도 버전·작성자·대상·적용 결과를 가집니다. 보존됐다는 사실이 조회 허용을 뜻하지는 않습니다.</div></div>`)}</div><div class="section-gap">${panel('이번 세션의 접근·변경 감사 예시',auditTable())}</div>`}
function renderHealth(){return `<div class="stats">${stat('수집 처리량 예시','18.4k','events/s','합성 부하 · 실제 수용량 검증 아님')}${stat('근거 조회 p95 예시','142','ms','합성 조회 창 · 접근 정책 포함 전제','#a4b9d2')}${stat('수집·분석 큐',state.scaleRun?'31':'67','%','정한 자원 예산 대비 점유 예시','#c5b087')}${stat('수집 상태','부분','','업무 장애와 관측 경로 장애를 분리','#b2a5ca')}</div><div class="grid cols-3">${[['수집·갱신','input → validate → reconcile','수집기 중단과 유실·재시도를 원래 업무 서비스의 실패와 구분합니다.'],['분석·저장','analyze → snapshot → index','분석 입력과 작업을 격리하고 빌드별 결과·과거 참조를 유지합니다.'],['조회·에이전트','authorize → query → evidence','현재 권한·조회 상한·버전 일치와 출처·한계를 함께 반환합니다.']].map(([t,s,d])=>panel(t,`<div class="pad"><div class="mono tiny muted">${s}</div><p class="subtext section-gap" style="margin-bottom:0">${d}</p></div>`,statusBadge(t==='수집·갱신'?'partial':'healthy'))).join('')}</div><div class="grid cols-2 section-gap">${panel('자동 확장과 공정성',`<div class="pad"><svg class="chart" viewBox="0 0 440 110" role="img" aria-label="합성 부하 증가와 큐 사용량 변화"><path d="M0 85H440M0 50H440M0 15H440" stroke="#edf1f6" fill="none"/><path d="M0 90L40 86L80 80L120 65L160 38L200 22L240 35L280 55L320 70L360 72L400 76L440 74" fill="none" stroke="#b4c996" stroke-width="2"/><path d="M0 94L40 93L80 88L120 80L160 70L200 55L240 45L280 45L320 43L360 44L400 44L440 44" fill="none" stroke="#acbdd4" stroke-width="1.5" stroke-dasharray="4 3"/><text x="0" y="108">합성 시간 구간</text><text x="295" y="108">입력·적체·복구를 분리</text></svg><div class="metric-line"><span>connector worker</span><b>${state.scaleRun?'5':'3'} replicas · 상한 8 예시</b></div><div class="metric-line"><span>조직별 자원 예산</span><b>폭주 작업의 격리·상한 적용</b></div><button class="btn section-gap" data-scale>확장 결과 시뮬레이션</button><p class="subtext" style="font-size:8px;margin:12px 0 0">고정 자원·장애 중 여유·축소와 작업 인계도 별도로 검증할 대상입니다.</p></div>`)}${panel('복구·보존·업그레이드',`<div class="pad"><dl class="kv"><dt>복구 목표</dt><dd>RPO 5분 / RTO 30분 · 화면용 정책 예시</dd><dt>복구 확인</dt><dd>설정·키·권한·빌드별 근거를 포함한 복원 리허설</dd><dt>상태 구분</dt><dd>백업 생성 성공과 실제 복원 성공을 분리</dd><dt>보존 예산</dt><dd>근거·사건·자산 이력의 보존량·기간·비용</dd><dt>호환성</dt><dd>SDK·agent·collector·API·스키마의 조합</dd><dt>독립 운영</dt><dd>플랫폼 장애 중에도 확인할 외부 운영 경로</dd></dl><div class="notice blue section-gap" style="margin-bottom:0">표시된 목표·곡선·상태는 최종 제품의 화면 구성을 위한 합성 예시입니다. 실제 기업 운영·복구·성능 검증을 주장하지 않습니다.</div></div>`)}</div>`}
function showService(id){const s=visibleServices().find(s=>s.id===id);if(!s){toast('현재 조회 범위에 없는 서비스입니다.');return}state.service=s.id;const linked=visibleResources().filter(r=>r.links.includes(id));openDialog(s.id,`${team(s.team).name} · ${envLabel(s.env)} · ${s.owner}`,`<div class="actions" style="margin-bottom:14px">${statusBadge(s.status)}${badge(s.runtime)}${badge('빌드 '+s.build,'blue')}</div><div class="detail-split"><div><h3 class="mini-heading">서비스와 실행 식별</h3><dl class="kv"><dt>업무 기능</dt><dd>${esc(s.path)}</dd><dt>저장소</dt><dd class="mono">${s.repo}</dd><dt>Revision</dt><dd class="mono">${s.revision}</dd><dt>실행 artifact</dt><dd class="mono">${s.artifact}</dd><dt>메서드</dt><dd class="mono">${s.method}()</dd><dt>원본</dt><dd>합성 카탈로그·배포·실행 fixture</dd></dl></div><div><h3 class="mini-heading">연결된 자원</h3>${linked.length?linked.map(r=>`<div class="metric-line"><button class="link" data-resource="${r.id}">${r.id}</button>${badge(r.type)}</div>`).join(''):'<p class="subtext">현재 합성 범위에 연결 자원이 없습니다.</p>'}</div></div><div class="actions section-gap"><button class="btn primary" data-code-service="${s.id}">코드·실행 조사 ↗</button>${goBtn('infra','인프라')}<button class="btn" data-obs-service="${s.id}" data-obs-target="overview">트래픽·로그·트레이스 ↗</button>${goBtn('cmdb','구성 이력')}${goBtn('security','보안 근거')}</div><p class="subtext section-gap" style="font-size:9px;margin-bottom:0">이름이 같아도 다른 빌드나 배포의 근거를 자동으로 합치지 않습니다.</p>`,'SERVICE CATALOG')}
function showResource(id){const r=visibleResources().find(r=>r.id===id);if(!r){toast('현재 조회 범위에 없는 자원입니다.');return}const linked=r.links.map(id=>visibleServices().find(s=>s.id===id)).filter(Boolean),s3=r.type==='S3';openDialog(r.id,`${r.type} · ${r.name} · ${envLabel(r.env)}`,`<div class="actions" style="margin-bottom:15px">${statusBadge(r.status)}${badge(team(r.team).name)}${badge(r.category,'blue')}</div><dl class="kv"><dt>자원 식별</dt><dd class="mono">fixture-resource://${r.env}/${r.id}</dd><dt>설정 revision</dt><dd class="mono">${r.revision}</dd><dt>담당 조직</dt><dd>${team(r.team).owner}</dd><dt>출처</dt><dd>${r.source}</dd><dt>수집 시각</dt><dd>${r.captured} · 합성 예시</dd><dt>관계 유형</dt><dd>선언·구성 관계. 실제 호출 여부는 별도 실행 근거로 확인</dd>${s3?'<dt>네트워크 관계</dt><dd>S3 서비스 자원 · 서브넷 내부에 배치된 서버가 아님. VPC endpoint 또는 외부 송신 경로와 별도 연결</dd><dt>권한·암호화</dt><dd>실행 역할·버킷 정책·KMS 키와 연결한 예시</dd><dt>접근 기록</dt><dd>객체 데이터 이벤트 일부 미수집 · 접근이 없었다는 뜻이 아님</dd>':''}</dl><h3 class="mini-heading section-gap">이 자원을 사용하는 서비스</h3><div class="tags">${linked.map(s=>`<button class="btn small" data-service="${s.id}">${s.id} ↗</button>`).join('')||badge('현재 범위에 확인된 서비스 없음')}</div><div class="actions section-gap">${goBtn('cmdb','변경 이력')}${goBtn('network','네트워크 구성')}${goBtn('security','관련 보안 이벤트')}</div><div class="notice blue section-gap" style="margin-bottom:0">연결·권한·시간 범위가 맞는 근거만 함께 조회하는 화면입니다. 공급원 장애를 자원 삭제로 처리하지 않습니다.</div>`,'ASSET & CONFIGURATION')}
function showEvent(id){const e=visibleEvents().find(e=>e.id===id);if(!e){toast('현재 조회 범위의 사건이 아닙니다.');return}state.service=e.service;if(e.service==='payment-api')state.vpc='vpc-payments';openDialog(e.id+' · '+e.title,`${e.service} · ${e.time} KST · ${e.kind}`,`<div class="notice"><strong>현재 판정: 조사 중</strong>${e.detail}</div><dl class="kv"><dt>실행 대상</dt><dd>${e.service} · build ${svc(e.service).build}</dd><dt>관측 구간</dt><dd>14:20–14:32 KST</dd><dt>관계 출처</dt><dd>실행 fixture · 구성 snapshot · 공급원 상태</dd><dt>영향 범위</dt><dd>선언·관측된 의존 관계를 조회하되 실제 전파 여부는 구분</dd><dt>부족한 근거</dt><dd>전체 요청·패킷·메서드의 완전 수집은 보장하지 않음</dd></dl><div class="actions section-gap"><button class="btn primary" data-go="${e.target}">관련 영역에서 조사 ↗</button><button class="btn" data-code-service="${e.service}">실행 근거</button>${goBtn('cmdb','당시 구성')}${goBtn('map','서비스 관계')}</div>`,'INVESTIGATION')}
function showSecurity(id){const e=visibleSecurity().find(e=>e.id===id);if(!e)return;state.service=e.service;openDialog(e.id+' · '+e.title,`${e.service} · ${e.time} KST · ${e.source}`,`<div class="actions" style="margin-bottom:12px">${badge(e.severity,e.severity==='high'?'red':'amber')}${badge(e.state)}${badge('합성 이벤트')}</div><p class="subtext">${e.detail}</p><dl class="kv"><dt>대상 자산</dt><dd>${resources.filter(r=>r.links.includes(e.service)).map(r=>r.id).slice(0,4).join(' · ')}</dd><dt>연결 근거</dt><dd>자원 식별 + 당시 배포 관계 + 유효 시간</dd><dt>현재 권한</dt><dd>허용된 이벤트 요약 · 민감 원본 제외</dd><dt>원인 판정</dt><dd>미확정 · 관측 사실과 가설을 구분</dd></dl><div class="actions section-gap"><button class="btn" data-code-service="${e.service}">실행·버전 확인</button>${goBtn('cmdb','구성 변경')}${goBtn('automation','대응 제안·승인')}</div>`,'SECURITY INVESTIGATION')}
function showMethod(kind){const s=selectedService();if(!s)return;const m=methodData(s);const name=m[kind]||m.main;openDialog(name,`${s.id} · module ${s.module} · runtime build ${s.build}`,`<dl class="kv"><dt>메서드 식별</dt><dd class="mono">${s.module}::${name}</dd><dt>런타임</dt><dd>${s.runtime}</dd><dt>실행 빌드</dt><dd>${s.build} · ${s.artifact}</dd><dt>분석 빌드</dt><dd>${state.build==='previous'?s.build-1:s.build}</dd><dt>소스 연결</dt><dd>${state.build==='previous'?'보류 · 빌드 불일치':'같은 빌드의 합성 식별 근거'}</dd><dt>관계 유형</dt><dd>${state.codeTab==='static'?'해당 분석 범위의 정적 후보':'선택한 합성 실행에서 관측한 관계'}</dd><dt>CPU 시간</dt><dd>이 요청의 CPU 시간은 미측정</dd><dt>수집 범위</dt><dd>app-only-r7 · 일부 요청 표본 · 프레임워크 전체 계측 아님</dd></dl><div class="notice blue section-gap" style="margin-bottom:0">실제 형식에서는 언어별 overload·모듈·서명 정보를 보존해야 합니다. 이 화면은 메서드 수준 탐색 흐름을 위한 합성 예시입니다.</div>`,'METHOD EVIDENCE')}
function showConnector(id){const c=connectors.find(c=>c.id===id);if(!c)return;openDialog(c.name+' · 연결 범위',c.scope,`<div style="margin-bottom:15px">${statusBadge(c.state)}</div><dl class="kv"><dt>마지막 확인</dt><dd>${c.last} KST · 합성 예시</dd><dt>수집 범위</dt><dd>${c.detail}</dd><dt>권한 경계</dt><dd>연결 자격과 조회자·실행기의 권한을 분리</dd><dt>갱신 트리거</dt><dd>공급원별 변경 알림 + 주기 원본 재확인</dd><dt>결과 상태</dt><dd>수신·처리 성공·부분 완료·오래됨을 구분</dd><dt>실패 정책</dt><dd>마지막 성공 결과 유지 · 미확인 범위 표시</dd></dl><div class="actions section-gap"><button class="btn primary" data-sync>원본 재확인 재현</button>${goBtn('automation','갱신 작업 흐름')}</div>`,'SOURCE CONNECTION')}
function showActionReview(){openDialog('조치 제안 검토','플랫폼 connector worker 확장 · 합성 환경',`<div class="notice blue"><strong>현재 목업 안의 승인·실행 절차입니다.</strong>실제 조직의 승인이나 클라우드 변경을 수행하지 않습니다.</div><dl class="kv"><dt>제안 근거</dt><dd>수집 작업 적체와 정해진 자원 예산의 합성 예시</dd><dt>대상</dt><dd>connector worker · fixture deployment</dd><dt>변경</dt><dd>replicas 3 → 5</dd><dt>되돌리기</dt><dd>replicas 5 → 3 · 현재 부하와 작업 인계 재확인</dd><dt>권한</dt><dd>조회·제안·승인·실행을 각각 확인</dd><dt>감사</dt><dd>행위자·대리 신원·대상·정책·결과 기록</dd></dl><div class="actions section-gap">${state.workflow==='proposed'?'<button class="btn primary" data-approve-action>승인 절차 재현</button>':state.workflow==='approved'?'<span class="badge green">승인 절차 재현 완료</span>':'<button class="btn" data-reset-action>새 제안으로 다시 체험</button>'}</div>`,'CHANGE REVIEW')}
function renderSignals(){const s=selectedService();if(!s)return panel('관측 신호','<div class="empty">현재 범위의 서비스가 없습니다.</div>');return `${panel('관측 신호의 대상과 버전',`<div class="explore-toolbar"><div class="actions">${serviceSelector()}${badge('build '+s.build,'blue')}</div><button class="btn small" data-return-code>메서드·요청으로 돌아가기</button></div><div class="pad"><p class="subtext" style="margin:0">로그·트레이스·프로파일은 서로 다른 수집 경로를 가집니다. 빌드·프로세스·시간이 맞는 근거만 연결합니다.</p></div>`)}<div class="grid cols-2 section-gap">${panel('허용된 로그 메타데이터',table(['시각','수준','구조화된 필드'],[`<tr><td>14:28:12</td><td>${badge(s.status==='incident'?'ERROR':'INFO',s.status==='incident'?'red':'blue')}</td><td class="mono">service=${s.id}<small>build=${s.build} · request.fixture=run-17</small></td></tr>`,`<tr><td>14:28:13</td><td>${badge('INFO','blue')}</td><td class="mono">operation=${s.action}<small>본문·인수·반환값·예외 메시지 제외</small></td></tr>`],true))}${panel('빌드·프로세스의 프로파일',`<div class="pad"><p class="subtext">해당 프로세스의 CPU 샘플 분포를 표현한 합성 그림입니다. 이 요청의 CPU 시간이나 지연 원인을 직접 입증하지 않습니다.</p><svg viewBox="0 0 420 105" role="img" aria-label="합성 CPU 샘플의 계층 그림"><rect x="0" y="73" width="420" height="24" rx="2" fill="#dbe6c9"/><rect x="0" y="47" width="235" height="23" rx="2" fill="#c2d3a7"/><rect x="238" y="47" width="182" height="23" rx="2" fill="#d6dfed"/><rect x="0" y="21" width="134" height="23" rx="2" fill="#b5c796"/><rect x="137" y="21" width="98" height="23" rx="2" fill="#d5c6a6"/><text x="12" y="89" font-size="9" fill="#6b8051">process fixture · build ${s.build}</text><text x="10" y="63" font-size="9" fill="#6c7f55">application samples</text><text x="249" y="63" font-size="9" fill="#8294ae">runtime samples</text></svg><dl class="kv section-gap"><dt>집계 구간</dt><dd>14:20–14:32 KST · 합성 프로세스</dd><dt>Trace 연결</dt><dd>직접 연결 미확인 · 시간·빌드 범위의 관련 근거</dd></dl></div>`,badge('독립 샘플','blue'))}</div>`}
// Local, deterministic telemetry fixtures. No collectors or remote calls.
Object.assign(state, {obsTab:'overview', obsService:'all', obsWindow:15, obsFilter:'all', obsLevel:'all', obsQuery:''});
const obsEnd = Date.parse('2026-11-12T14:32:00+09:00');
const obsTabs = [['overview','트래픽 개요'],['metrics','메트릭'],['logs','로그 탐색'],['traces','트레이스 탐색'],['profiles','프로파일']];
const obsTraces = services.flatMap((s,i) => [1,7,28].map((ago,k) => {
  const failed = k===0 && s.error>.3;
  const duration = Math.round(s.p95 * [1,.48,.72][k]);
  const id = (0x7a0000+i*20+k).toString(16).padStart(32,'0');
  const start = obsEnd - ago*60000 - i*710;
  const async = /consumer|Streams|Kafka/i.test(s.runtime);
  return {id,service:s.id,build:s.build,revision:s.revision,artifact:s.artifact,route:s.path,operation:s.action,start,duration,failed,status:failed?'ERROR':'OK',http:async?null:failed?503:200,kind:async?'CONSUMER':'SERVER',spanId:(0x7100+i*20+k).toString(16).padStart(16,'0'),sampling:'synthetic retained sample',source:'inline trace fixture'};
}));
const obsLogs = obsTraces.flatMap((t,i) => [0,1].map(n => ({
  id:'log-fixture-'+i+'-'+n,service:t.service,build:t.build,traceId:t.id,spanId:t.spanId,
  timestamp:t.start+n*3,level:t.failed&&n===1?'ERROR':'INFO',
  event:n===0?'operation.started':t.failed?'dependency.timeout':'operation.completed',
  message:n===0?'업무 처리 시작':t.failed?'의존 자원 응답 지연 · 허용된 오류 코드':'업무 처리 완료',source:'inline structured log fixture'
}))).concat(services.filter(s=>['notification-worker','connector-worker'].includes(s.id)).map((s,i)=>({
  id:'log-unlinked-'+i,service:s.id,build:s.build,traceId:null,spanId:null,timestamp:obsEnd-3*60000,
  level:'WARN',event:'context.unresolved',message:'수집된 로그의 요청 연결 정보가 없습니다.',source:'inline structured log fixture'
}))).sort((a,b)=>b.timestamp-a.timestamp);

function obsTime(t){return new Date(t+9*3600000).toISOString().slice(11,19)}
function obsWindowText(){return obsTime(obsEnd-state.obsWindow*60000).slice(0,5)+'–14:32 KST'}
function obsScopedServices(){const list=visibleServices();return state.obsService==='all'?list:list.filter(s=>s.id===state.obsService)}
function obsInWindow(t){return t>=obsEnd-state.obsWindow*60000&&t<=obsEnd}
function obsScopeTraces(){const ids=new Set(obsScopedServices().map(s=>s.id));return obsTraces.filter(t=>ids.has(t.service)&&obsInWindow(t.start))}
function obsFilteredTraces(){const q=state.obsQuery.toLowerCase();return obsScopeTraces().filter(t=>(state.obsFilter==='all'||state.obsFilter==='error'&&t.failed||state.obsFilter==='slow'&&t.duration>=500)&&(!q||[t.id,t.service,t.route,t.operation,t.status].join(' ').toLowerCase().includes(q)))}
function obsScopeLogs(){const ids=new Set(obsScopedServices().map(s=>s.id));return obsLogs.filter(l=>ids.has(l.service)&&obsInWindow(l.timestamp))}
function obsFilteredLogs(){const q=state.obsQuery.toLowerCase();return obsScopeLogs().filter(l=>(state.obsLevel==='all'||state.obsLevel===l.level)&&(!q||[l.service,l.traceId||'',l.level,l.event,l.message].join(' ').toLowerCase().includes(q)))}
function obsHistogram(s,count){const portions=[.35,.30,.20,.10,.04,.01],factors=[.16,.30,.55,1,1.5,3];let used=0;return portions.map((p,i)=>{const n=i===5?count-used:Math.floor(count*p);used+=n;return [Math.max(1,Math.round(s.p95*factors[i])),n]})}
function obsQuantile(hist,p){const values=hist.filter(v=>v[1]>0).sort((a,b)=>a[0]-b[0]);const total=values.reduce((a,b)=>a+b[1],0);if(!total)return null;let seen=0;for(const [ms,count]of values){seen+=count;if(seen>=Math.ceil(total*p))return ms}return values.at(-1)[0]}
function obsMinuteStats(list,ago){
  if(ago===8)return null; // Deliberate collection gap, never interpolated.
  let count=0,errors=0;const histogram=[];
  list.forEach(s=>{const i=services.indexOf(s),shape=.82+.14*Math.sin((60-ago)/4+i*.7)+.12*Math.cos(ago/7+i);const n=Math.max(0,Math.round(s.rps*60*shape));count+=n;errors+=Math.round(n*s.error/100);histogram.push(...obsHistogram(s,n))});
  return {count,errors,histogram,rps:count/60,error:count?errors/count*100:0,p95:obsQuantile(histogram,.95)};
}
function obsStats(list=obsScopedServices()){
  const bins=Array.from({length:state.obsWindow},(_,i)=>({ago:state.obsWindow-1-i,value:obsMinuteStats(list,state.obsWindow-1-i)}));
  const valid=bins.filter(b=>b.value),count=valid.reduce((a,b)=>a+b.value.count,0),errors=valid.reduce((a,b)=>a+b.value.errors,0);
  return {bins,count,errors,rps:valid.length?count/(valid.length*60):0,error:count?errors/count*100:0,p95:obsQuantile(valid.flatMap(b=>b.value.histogram),.95),validMinutes:valid.length};
}
function obsNum(v,d=0){return v==null?'—':v.toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d})}
function obsChart(title,key,unit,color){
  const bins=obsStats().bins,values=bins.map(b=>b.value?.[key]??null),max=Math.max(1,...values.filter(v=>v!=null))*1.18;
  const x=i=>46+i*548/Math.max(1,bins.length-1),y=v=>139-v/max*106;let pen=false,d='';
  values.forEach((v,i)=>{if(v==null){pen=false;return}d+=(pen?'L':'M')+x(i).toFixed(1)+' '+y(v).toFixed(1)+' ';pen=true});
  const gaps=values.flatMap((v,i)=>v==null?[`<rect x="${x(i)-5}" y="25" width="10" height="114" fill="#f5e7d4"><title>${obsTime(obsEnd-bins[i].ago*60000)} · 미수집</title></rect>`]:[]).join('');
  return panel(title,`<div class="obs-chart"><svg viewBox="0 0 620 178" role="img" aria-label="${title} 추이 · 14:24 구간 미수집"><text x="12" y="13">${unit}</text>${[0,.5,1].map(p=>`<path d="M46 ${139-p*106}H594" stroke="#e9edf3"/><text x="3" y="${143-p*106}">${obsNum(max*p,key==='error'?1:0)}</text>`).join('')}${gaps}<path d="${d}" stroke="${color}" fill="none" stroke-width="2.4"/>${values.map((v,i)=>v==null?'':`<circle cx="${x(i)}" cy="${y(v)}" r="3.3" fill="${color}"><title>${obsTime(obsEnd-bins[i].ago*60000).slice(0,5)} · ${obsNum(v,key==='error'?2:0)} ${unit}</title></circle>`).join('')}<text x="46" y="164">${obsTime(obsEnd-(state.obsWindow-1)*60000).slice(0,5)}</text><text x="560" y="164">14:32</text></svg><div class="obs-chart-note"><span><i style="background:${color}"></i> 합성 집계</span><span><i style="background:#f5e7d4"></i> 수집 공백 · 보간 없음</span></div></div>`);
}
function obsControls(){return `<div class="panel obs-controls"><div class="explore-toolbar"><div class="actions"><label class="obs-label">대상 서비스<select id="obs-service" class="select"><option value="all">현재 범위의 전체 서비스</option>${visibleServices().map(s=>`<option value="${s.id}" ${state.obsService===s.id?'selected':''}>${s.id}</option>`).join('')}</select></label><label class="obs-label">조회 시간<select id="obs-window" class="select"><option value="15" ${state.obsWindow===15?'selected':''}>최근 15분 · 예시</option><option value="60" ${state.obsWindow===60?'selected':''}>최근 1시간 · 예시</option></select></label></div><div class="obs-window">${badge('합성 텔레메트리','blue')}<b>2026.11.12 · ${obsWindowText()}</b><small>고정된 시점의 탐색 체험 · 실시간 수집 아님</small></div></div><div class="tabline obs-tabs">${obsTabs.map(([id,name])=>`<button data-obs-tab="${id}" class="${state.obsTab===id?'active':''}">${name}</button>`).join('')}</div></div>`}
function obsSummary(){const m=obsStats();return `<div class="stats section-gap">${stat('관측된 처리 건수',obsNum(m.count),'operations',`HTTP 요청 · 이벤트 처리 · ${m.validMinutes}/${state.obsWindow}분 수집`)}${stat('평균 처리량',obsNum(m.rps,1),'/s','수집된 시간 기준 · 서비스 처리 건수 합계','#9bb9da')}${stat('실패 비율',obsNum(m.error,2),'%',`${obsNum(m.errors)}건 실패 · 합성 집계`,'#d4a090')}${stat('처리 지연 p95',obsNum(m.p95),'ms','합성 지연 히스토그램을 합쳐 계산','#b7a5cd')}</div>`}
function obsServiceRows(){return obsScopedServices().map(s=>{const m=obsStats([s]);return `<tr><td>${serviceLink(s)}<small>${s.path}</small></td><td>${s.runtime}<small>build ${s.build} · ${envLabel(s.env)}</small></td><td>${obsNum(m.rps,1)} /s<small>${obsNum(m.count)} operations</small></td><td>${obsNum(m.error,2)}%</td><td>${obsNum(m.p95)} ms</td><td><div class="actions"><button class="btn small" data-obs-service="${s.id}" data-obs-target="logs">로그</button><button class="btn small" data-obs-service="${s.id}" data-obs-target="traces">트레이스</button></div></td></tr>`})}
function obsOverview(){return `${obsSummary()}<div class="grid cols-3 section-gap">${obsChart('서비스 처리량','rps','operations/s','#729d89')}${obsChart('실패 비율','error','%','#c68a7c')}${obsChart('지연 분포 · p95','p95','ms','#9284b9')}</div><div class="obs-correlation section-gap"><div><span class="obs-kicker">CONNECTED INVESTIGATION</span><h3>트래픽 변화에서 실행 근거까지</h3><p>서비스와 시간 범위를 유지하며 신호를 넘나듭니다.</p></div><div class="obs-journey">${[['metrics','메트릭'],['logs','구조화 로그'],['traces','요청·Span'],['profiles','프로파일']].map(([id,n])=>`<button data-obs-tab="${id}">${n}<span>↗</span></button>`).join('')}</div></div><div class="section-gap">${panel('서비스·엔드포인트 분석',table(['서비스 / 업무','런타임 / 배포','처리량','실패 비율','지연 p95','탐색'],obsServiceRows()),badge(obsScopedServices().length+' services'))}</div><div class="obs-caption">서비스별 처리 건수의 합계에는 내부 호출과 소비자 실행도 포함됩니다. 전사 사용자 요청 수로 해석하지 않습니다. 아래 로그·트레이스는 독립된 보존 표본이며 전체 처리 건수와 구분합니다.</div>`}
function obsMetrics(){const list=obsScopedServices();return `${obsSummary()}<div class="grid cols-2 section-gap">${obsChart('처리량과 수집 공백','rps','operations/s','#729d89')}${obsChart('지연 히스토그램 · p95','p95','ms','#9284b9')}</div><div class="grid cols-2 section-gap">${obsChart('실패 처리 비율','error','%','#c68a7c')}${panel('실행 자원·런타임 메트릭',table(['대상','CPU 사용률','메모리 사용률','실행 형태'],list.map(s=>{const i=services.indexOf(s);return `<tr><td>${serviceLink(s)}</td><td>${33+(i*7)%50}%<small>프로세스 CPU / 할당 quota · 예시</small></td><td>${41+(i*3)%35}%<small>working set / limit · 예시</small></td><td>${s.runtime}</td></tr>`})),badge('구간 평균 · 합성값'))}</div><div class="obs-caption">지연 백분위는 서비스별 p95의 평균이 아닙니다. 동일 단위의 합성 히스토그램을 합쳐 산출합니다. 결측 구간과 미측정 값은 0으로 채우지 않습니다.</div>`}
function obsSearch(kind,count){return `<div class="explore-toolbar"><form id="obs-search-form" class="obs-search"><label class="sr-only" for="obs-query">${kind==='logs'?'로그':'트레이스'} 검색</label><input id="obs-query" class="filter-input" maxlength="100" placeholder="서비스 · Trace ID · 이벤트 검색" value="${esc(state.obsQuery)}"><button class="btn small" type="submit">검색</button><button class="btn small" type="button" data-obs-clear>초기화</button></form><div class="actions">${kind==='logs'?`<label class="obs-label">수준<select id="obs-level" class="select">${['all','INFO','WARN','ERROR'].map(v=>`<option value="${v}" ${state.obsLevel===v?'selected':''}>${v==='all'?'모든 수준':v}</option>`).join('')}</select></label>`:`<div class="segmented">${[['all','전체'],['error','실패'],['slow','500ms 이상']].map(([k,n])=>`<button data-obs-filter="${k}" class="${state.obsFilter===k?'active':''}">${n}</button>`).join('')}</div>`}<span class="result-count">${count}개 표본</span></div></div>`}
function obsRenderLogs(){const list=obsFilteredLogs();return `<div class="section-gap">${panel('구조화 로그 탐색',obsSearch('logs',list.length)+table(['시각 · KST','수준','서비스 / 버전','이벤트','요청 연결','상세'],list.map(l=>`<tr><td class="mono">${obsTime(l.timestamp)}</td><td>${badge(l.level,l.level==='ERROR'?'red':l.level==='WARN'?'amber':'blue')}</td><td>${serviceLink(svc(l.service))}<small>build ${l.build}</small></td><td class="mono">${l.event}<small>${l.message}</small></td><td>${l.traceId?`<button class="link mono" data-obs-trace="${l.traceId}">${l.traceId.slice(-10)} ↗</button>`:badge('연결 미확인','amber')}</td><td><button class="btn small" data-obs-log="${l.id}">필드 보기</button></td></tr>`)),badge('허용된 필드만 표시'))}</div><div class="obs-caption">서비스·환경·시간 조건으로 조회한 보존 표본입니다. 로그 본문·인수·반환값·개인정보는 포함하지 않습니다. Trace ID가 없는 로그를 시간만으로 특정 요청에 연결하지 않습니다.</div>`}
function obsRenderTraces(){const list=obsFilteredTraces().sort((a,b)=>b.start-a.start);return `<div class="section-gap">${panel('분산 트레이스 탐색',obsSearch('traces',list.length)+table(['시각 · KST','진입 서비스 / 업무','결과','경과 시간','배포 빌드','Trace ID'],list.map(t=>`<tr><td class="mono">${obsTime(t.start)}</td><td>${serviceLink(svc(t.service))}<small>${t.route} · ${t.kind}</small></td><td>${badge(t.status,t.failed?'red':'green')}<small>${t.http==null?'이벤트 처리':t.http+' · HTTP fixture'}</small></td><td><button class="link" data-obs-trace="${t.id}">${obsNum(t.duration)} ms ↗</button></td><td class="mono">${t.build}<small>${t.revision}</small></td><td><button class="link mono" data-obs-trace="${t.id}">${t.id.slice(-10)} ↗</button></td></tr>`)),badge('트레이스 보존 표본','blue'))}</div><div class="obs-caption">상세에서 서비스 간 호출·메서드·외부 의존 자원의 Span을 확인합니다. 샘플링한 요청의 목록이며 메트릭 전체 건수와 일치하지 않습니다. 이벤트 소비자의 원래 발행 요청은 전달된 연결 근거가 있을 때만 표시합니다.</div>`}
function obsSpans(t){const s=svc(t.service),m=methodData(s),depService=t.service==='order-service'?'payment-api':s.id;const dep=svc(depService);const call=t.service==='order-service'?'PaymentClient.authorize()':m.dependency;return [
  {id:t.spanId,parent:null,service:s.id,name:m.entry,offset:0,duration:t.duration,build:s.build,kind:t.kind},
  {id:t.spanId.slice(0,-2)+'21',parent:t.spanId,service:s.id,name:m.main,offset:Math.round(t.duration*.01),duration:Math.max(1,Math.round(t.duration*.96)),build:s.build,kind:'INTERNAL'},
  {id:t.spanId.slice(0,-2)+'22',parent:t.spanId.slice(0,-2)+'21',service:s.id,name:'validateInput() · private',offset:Math.round(t.duration*.03),duration:Math.max(1,Math.min(3,Math.round(t.duration*.1))),build:s.build,kind:'INTERNAL'},
  {id:t.spanId.slice(0,-2)+'23',parent:t.spanId.slice(0,-2)+'21',service:s.id,name:call,offset:Math.round(t.duration*.08),duration:Math.round(t.duration*.86),build:s.build,kind:'CLIENT'},
  ...(t.service==='order-service'?[{id:t.spanId.slice(0,-2)+'24',parent:t.spanId.slice(0,-2)+'23',service:dep.id,name:dep.method+'()',offset:Math.round(t.duration*.10),duration:Math.round(t.duration*.79),build:dep.build,kind:'SERVER'}]:[])
]}
function obsTraceDetail(id){if(id===flowTraceId){if(!obsScopeTraces().some(t=>t.id===id))return;document.querySelector('dialog[open]')?.close();navigate('flow');return}const t=obsScopeTraces().find(t=>t.id===id);if(!t){toast('현재 서비스·시간 범위에 없는 트레이스입니다.');return}const s=svc(t.service),spans=obsSpans(t),logs=obsScopeLogs().filter(l=>l.traceId===t.id);const outside=spans.some(p=>!visibleServices().some(v=>v.id===p.service));openDialog('요청 실행 · '+t.service,`${obsTime(t.start)} KST · ${t.duration} ms · build ${t.build}`,`<div class="actions">${badge(t.status,t.failed?'red':'green')}${badge(t.kind,'blue')}${badge('관측된 합성 Span')}</div><p class="mono obs-trace-id">trace_id=${t.id}</p><div class="obs-waterfall">${spans.map((p,i)=>{const allowed=visibleServices().some(v=>v.id===p.service);return `<div class="obs-span"><div class="obs-span-label"><b>${allowed?p.name:'조회 범위 밖의 호출'}</b><small>${allowed?p.service+' · build '+p.build:'현재 팀·환경 필터 밖'} · ${p.kind}</small></div><div class="obs-span-track"><i style="left:${p.offset/t.duration*100}%;width:${Math.max(1,p.duration/t.duration*100)}%;background:${i>2?'#b7a5cd':'#a6c69a'}"></i></div><span>${p.duration} ms</span></div>`}).join('')}</div>${outside?'<div class="notice">일부 호출 대상은 현재 조회 필터 밖에 있어 이름과 버전을 생략했습니다. 실제 접근 제어는 구현하지 않은 목업입니다.</div>':''}<dl class="kv section-gap"><dt>배포 식별</dt><dd>${t.artifact} · ${t.revision}</dd><dt>전체 경과 시간</dt><dd>${t.duration} ms · 중첩 Span을 합산하지 않음</dd><dt>CPU 시간</dt><dd>미측정 · 지연 시간과 구분</dd><dt>이벤트 연결</dt><dd>${t.kind==='CONSUMER'?'발행 요청 연결 미확인 · 소비자 실행만 확인':'이 요청 예시에 비동기 Span Link 없음'}</dd><dt>프로파일</dt><dd>같은 빌드·시간 범위의 관련 표본 · 이 요청과 직접 연결 미확인</dd><dt>출처 / 범위</dt><dd>inline trace fixture · 앱 패키지의 일부 요청·메서드</dd></dl><h3 class="mini-heading section-gap">동일 Trace ID의 로그 · ${logs.length}개</h3>${logs.map(l=>`<div class="metric-line"><span class="mono">${obsTime(l.timestamp)} · ${l.level} · ${l.event}</span><button class="link" data-obs-log="${l.id}">필드 ↗</button></div>`).join('')}<div class="actions section-gap"><button class="btn primary" data-obs-related-logs="${t.id}">이 요청의 로그 탐색</button><button class="btn" data-obs-code="${s.id}">해당 빌드의 코드 분석 ↗</button><button class="btn" data-obs-profile="${s.id}">빌드·시간 범위 프로파일</button></div>`,'DISTRIBUTED TRACE')}
function obsLogDetail(id){const l=obsScopeLogs().find(l=>l.id===id);if(!l)return;const fields={synthetic:true,timestamp:new Date(l.timestamp).toISOString(),severity:l.level,event:l.event,service:l.service,environment:svc(l.service).env,build:l.build,revision:svc(l.service).revision,trace_id:l.traceId,span_id:l.spanId,source:l.source,body:'excluded_by_policy',link:l.traceId?'explicit_trace_id':'unresolved'};openDialog('구조화 로그 필드',`${l.service} · ${obsTime(l.timestamp)} KST`,`<pre class="codebox">${esc(JSON.stringify(fields,null,2))}</pre><div class="actions section-gap">${l.traceId?`<button class="btn primary" data-obs-trace="${l.traceId}">연결된 트레이스 ↗</button>`:badge('Trace ID 없음 · 연결 미확인','amber')}<button class="btn" data-obs-code="${l.service}">해당 빌드의 코드 분석 ↗</button></div>`,'LOG EVIDENCE')}
function obsProfileSampleCount(s){return Math.round((1500+services.indexOf(s)*73)*state.obsWindow/15)}
function obsProfileRows(){return obsScopedServices().map((s,i)=>{const n=obsProfileSampleCount(s);return `<tr><td>${serviceLink(s)}<small>build ${s.build} · ${s.artifact}</small></td><td>CPU samples<small>${obsWindowText()} · process fixture</small></td><td>${obsNum(n)} samples</td><td>${s.method}()</td><td><button class="btn small" data-obs-profile="${s.id}">프로파일 열기 ↗</button></td></tr>`})}
function obsRenderProfiles(){return `<div class="section-gap">${panel('서비스·빌드별 프로파일',table(['대상 / 빌드','종류 / 시간','수집 샘플','애플리케이션 프레임','탐색'],obsProfileRows()),badge('독립 CPU 샘플','blue'))}</div><div class="obs-caption">프로파일은 프로세스의 CPU 샘플 분포입니다. 빌드·시간 범위로 관련 근거를 탐색하며, 개별 요청의 CPU 시간이나 지연 원인으로 단정하지 않습니다.</div>`}
function obsProfileDetail(id){const s=obsScopedServices().find(s=>s.id===id);if(!s)return;const n=obsProfileSampleCount(s),app=Math.round(n*.65),runtime=n-app,self=Math.round(app*.28);openDialog('CPU 프로파일 · '+s.id,`build ${s.build} · ${obsWindowText()} · 합성 프로세스`,`<p class="subtext">막대 너비는 샘플 수의 비율입니다. 프레임을 눌러 샘플 집계를 살펴보세요.</p><div class="obs-flame"><button style="width:100%;background:#dce8cc" data-obs-frame="process" data-obs-profile-service="${id}">process · ${obsNum(n)} samples</button><div><button style="width:65%;background:#bcd3a6" data-obs-frame="application" data-obs-profile-service="${id}">application · 65%</button><button style="width:35%;background:#cbd7ed" data-obs-frame="runtime" data-obs-profile-service="${id}">runtime · 35%</button></div><button style="width:65%;background:#d8c9a8" data-obs-frame="method" data-obs-profile-service="${id}">${s.method}()</button></div><dl class="kv section-gap"><dt>전체 샘플</dt><dd>${obsNum(n)} samples</dd><dt>Application</dt><dd>${obsNum(app)} inclusive samples</dd><dt>Runtime</dt><dd>${obsNum(runtime)} samples</dd><dt>메서드 self</dt><dd>${obsNum(self)} samples · 전체의 ${(self/n*100).toFixed(1)}%</dd><dt>실행 식별</dt><dd>${s.artifact} · ${s.revision}</dd><dt>Trace 연결</dt><dd>직접 연결 미확인 · 빌드·프로세스·시간 범위의 관련 표본</dd></dl><div class="actions section-gap"><button class="btn" data-obs-code="${s.id}">해당 빌드의 코드 분석 ↗</button></div>`,'CONTINUOUS PROFILING')}
function obsFrameDetail(kind,id){const s=obsScopedServices().find(s=>s.id===id);if(!s)return;const n=obsProfileSampleCount(s),app=Math.round(n*.65),runtime=n-app,counts={process:n,application:app,runtime,method:app},count=counts[kind];openDialog('프로파일 프레임 · '+kind,`${s.id} · build ${s.build}`,`<dl class="kv"><dt>Frame</dt><dd>${kind==='method'?s.method+'()':kind}</dd><dt>Inclusive samples</dt><dd>${obsNum(count)} · ${(count/n*100).toFixed(1)}%</dd><dt>Self samples</dt><dd>${kind==='method'?obsNum(Math.round(app*.28)):'미분해 · 전체를 self로 처리하지 않음'}</dd><dt>시간 범위</dt><dd>${obsWindowText()}</dd><dt>원본</dt><dd>inline synthetic CPU samples</dd></dl><button class="btn section-gap" data-obs-profile="${s.id}">프로파일로 돌아가기</button>`,'PROFILE FRAME')}
function renderObservability(){
  const list=visibleServices();if(state.obsService!=='all'&&!list.some(s=>s.id===state.obsService))state.obsService='all';
  return obsControls()+(!list.length?'<div class="panel empty section-gap">현재 팀·환경 범위에 분석할 서비스가 없습니다.</div>':({overview:obsOverview,metrics:obsMetrics,logs:obsRenderLogs,traces:obsRenderTraces,profiles:obsRenderProfiles}[state.obsTab])());
}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset,close=()=>document.querySelector('dialog[open]')?.close();
  if(d.obsTab){close();state.obsTab=d.obsTab;state.obsQuery='';navigate('observability')}
  else if(d.obsService){close();state.obsService=d.obsService;state.obsTab=d.obsTarget||'overview';state.obsQuery='';navigate('observability')}
  else if(d.obsTrace){obsTraceDetail(d.obsTrace)}
  else if(d.obsLog){obsLogDetail(d.obsLog)}
  else if(d.obsRelatedLogs){const t=obsScopeTraces().find(t=>t.id===d.obsRelatedLogs);if(!t)return;state.obsTab='logs';state.obsQuery=t.id;state.obsLevel='all';close();navigate('observability')}
  else if(d.obsCode){if(!obsScopedServices().some(s=>s.id===d.obsCode))return;state.service=d.obsCode;state.build='deployed';state.codeTab='static';close();navigate('code')}
  else if(d.obsFrame){obsFrameDetail(d.obsFrame,d.obsProfileService)}
  else if(d.obsProfile){obsProfileDetail(d.obsProfile)}
  else if(d.obsFilter){state.obsFilter=d.obsFilter;render()}
  else if(d.obsClear!==undefined){state.obsQuery='';state.obsFilter='all';state.obsLevel='all';render()}
});
