  const nodes=entries.map(([key,name])=>({key,service:s.id,label:key==='candidate'?'호출 대상 미해결':'해당 빌드의 호출 후보',kind:'STATIC',trace:'build '+s.build,elapsed:null,unknown:key==='candidate',error:false,legacy:key,methods:[{id:key+':static',name,index:0,elapsed:null,candidate:true}]}));
