function sgPlayback(items){const time=state.flowTime;if(items.some(n=>n.start<=time&&time<n.end))return {key:'active',label:'실행 중'};if(items.every(n=>time>=n.end))return {key:'done',label:'관측 완료'};return {key:'waiting',label:'대기'}}
