  if(cfg.type==='flow')return `<button class="btn small" ${m?`data-flow-method="${n.key}" data-flow-method-index="${m.index}" ${m.candidate?'data-flow-candidate':''}`:`data-flow-node="${n.key}"`}>근거 상세 ↗</button>`;
  if(cfg.type==='trace')return `<button class="btn small" ${m?.candidate?'data-task-candidate':`data-task-span="${n.index}"`}>근거 상세 ↗</button>`;
