function sgFocus(root){const v=sgViews.get(root.dataset.sgKey),viewport=root.querySelector('.sg-viewport'),group=v.layout.groups.find(g=>g.items.some(n=>n.key===v.selected)),scale=v.layout.scale||1;if(!group)return;viewport.scrollLeft=Math.max(0,(group.x+group.w/2)*scale-viewport.clientWidth/2);viewport.scrollTop=Math.max(0,(group.y+group.h/2)*scale-viewport.clientHeight/2);v.position=sgCapture(root);viewport.focus({preventScroll:true})}
function sgApplyZoom(root,zoom){const v=sgViews.get(root.dataset.sgKey);v.position=sgCapture(root);v.fit=false;v.auto=false;v.zoom=Math.max(60,Math.min(180,Math.round(zoom/5)*5));sgRedraw(root,false)}

document.addEventListener('click',e=>{
  const b=e.target.closest('button'),root=b?.closest('.sg-shell');if(!root||b.disabled)return;const v=sgViews.get(root.dataset.sgKey),cfg=v.model,d=b.dataset;
  if(d.sgLevel!==undefined){sgApplyZoom(root,[75,115,155][Number(d.sgLevel)])}
  else if(d.sgStep!==undefined){sgApplyZoom(root,sgZoom(v)+Number(d.sgStep))}
  else if(d.sgAuto!==undefined){v.position=sgCapture(root);v.fit=false;v.auto=true;sgRedraw(root,false)}
  else if(d.sgFit!==undefined){v.auto=false;v.zoom=75;v.fit=true;v.position=null;sgRedraw(root,false);const viewport=document.querySelector('.sg-viewport');viewport.scrollLeft=0;viewport.scrollTop=0;v.position=sgCapture(document.querySelector('.sg-shell'))}
  else if(d.sgSelect){v.selected=d.sgSelect;v.method=null;sgRedraw(root)}
  else if(d.sgMethod){v.selected=d.sgSource;v.method=d.sgMethod;sgRedraw(root)}
  else if(d.sgExpand){const group=v.layout.groups.find(g=>g.key===d.sgExpand);if(!group)return;v.fit=false;for(const n of group.items){if(group.open){v.expanded.delete(n.key);v.collapsed.add(n.key)}else{v.expanded.add(n.key);v.collapsed.delete(n.key)}}sgRedraw(root)}
  else if(d.sgFocus!==undefined){sgFocus(root)}
  else if(d.sgInspect!==undefined){v.inspectorExpanded=!v.inspectorExpanded;sgRedraw(root)}
});
document.addEventListener('input',e=>{
  const root=e.target.closest('.sg-shell');if(!root)return;const v=sgViews.get(root.dataset.sgKey);
  if(e.target.id==='sg-zoom'){sgApplyZoom(root,Number(e.target.value));return}
  if(e.target.closest('.sg-search')){v.query=e.target.value;const groups=sgGroups(v.model,v);root.querySelectorAll('[data-sg-node]').forEach(el=>el.classList.toggle('is-match',!!groups.find(g=>g.key===el.dataset.sgNode)?.matches));root.querySelector('.sg-match-count').textContent=v.query?groups.filter(g=>g.matches).length+'개 묶음':''}
});
document.addEventListener('submit',e=>{
  const form=e.target.closest('.sg-search');if(!form)return;e.preventDefault();const root=form.closest('.sg-shell'),v=sgViews.get(root.dataset.sgKey),q=v.query.trim().toLowerCase();if(!q)return;
  const n=v.model.nodes.find(n=>(n.service+' '+n.label+' '+n.methods.map(m=>m.name).join(' ')).toLowerCase().includes(q));if(!n){root.querySelector('.sg-match-count').textContent='일치하는 항목 없음';return}
  const m=n.methods.find(m=>m.name.toLowerCase().includes(q));v.fit=false;v.selected=n.key;v.method=m?.id||null;if(m){v.expanded.add(n.key);v.collapsed.delete(n.key)}sgRedraw(root);sgFocus(document.querySelector('.sg-shell'));
});
document.addEventListener('keydown',e=>{const root=e.target.closest('.sg-shell');if(!root||e.target!==root.querySelector('.sg-viewport'))return;const v=sgViews.get(root.dataset.sgKey);if(['+','=','-','0'].includes(e.key)){e.preventDefault();if(e.key==='0'){v.fit=false;v.auto=true;sgRedraw(root)}else sgApplyZoom(root,sgZoom(v)+(e.key==='-'?-15:15))}});

const sgOldTaskTrace=taskTraceDetail;
taskTraceDetail=function(){const t=obsScopeTraces().find(t=>t.id===state.traceId),el=document.createElement('div');el.innerHTML=sgOldTaskTrace();if(t){const graph=el.querySelector('.task-request-graph');if(graph)graph.outerHTML=sgMarkup(sgTraceModel(t))}return el.innerHTML};
const sgOldTaskCode=taskCode;
taskCode=function(){const el=document.createElement('div');el.innerHTML=sgOldTaskCode();const graph=el.querySelector('.method-map');if(graph&&state.build==='deployed')graph.outerHTML=sgMarkup(sgStaticModel(selectedService()));return el.innerHTML};
flowGraph=function(){return sgMarkup(sgFlowModel())};
const sgOldRenderFlow=renderFlow;
renderFlow=function(){const el=document.createElement('div');el.innerHTML=sgOldRenderFlow();el.querySelector('#flow-code')?.closest('label')?.remove();const player=el.querySelector('.flow-player'),controls=el.querySelector('.flow-controls');if(player&&controls){const label=controls.querySelector('#flow-static')?.closest('label');if(label)player.append(label);controls.remove()}const stats=el.querySelector('.stats'),graph=el.querySelector('.panel.section-gap');if(stats&&graph){stats.classList.add('section-gap');graph.after(stats)}return el.innerHTML};
const sgOldFlowUpdate=flowUpdate;
flowUpdate=function(){sgOldFlowUpdate();const root=document.querySelector('.sg-shell');if(root&&state.view==='flow'){const v=sgViews.get(root.dataset.sgKey);for(const g of v.layout.groups){const card=[...root.querySelectorAll('[data-sg-node]')].find(el=>el.dataset.sgNode===g.key);if(!card)continue;const status=sgPlayback(g.items);card.classList.remove('active','done','waiting');card.classList.add(status.key);card.querySelector('.sg-status').textContent=status.label}}};
const sgOldRender=render;
render=function(){sgRemember();sgOldRender();sgMount()};
// Open the new presentation at a concrete, fictional distributed request.
Object.assign(state,{view:'flow',traceId:flowTraceId,obsService:'api-gateway',service:'api-gateway',operation:'api-gateway::'+flowRoot.route,build:'deployed',flowAnalysis:'matched',flowCode:true,flowTime:1600});

render();
